            pd2_rr(2, 1) = pd2_rr(2, 1) + t_pd2_rr_01
            t_pd2_rr_02 = d_a(1)*d_a(3)*x12*x13*x14*x6 - d_a(1)*x18
            pd2_rr(1, 3) = pd2_rr(1, 3) + t_pd2_rr_02
            pd2_rr(3, 1) = pd2_rr(3, 1) + t_pd2_rr_02
            pd2_rr(2, 2) = pd2_rr(2, 2) + (-x10*x2 + x19*x2 + x8)
            t_pd2_rr_12 = d_a(2)*d_a(3)*x12*x13*x14*x6 - d_a(3)*x17
            pd2_rr(2, 3) = pd2_rr(2, 3) + t_pd2_rr_12
            pd2_rr(3, 2) = pd2_rr(3, 2) + t_pd2_rr_12
            pd2_rr(3, 3) = pd2_rr(3, 3) + (-x10*x3 + x19*x3 + x8)
            pd3_rrr(1, 1, 1) = &
               pd3_rrr(1, 1, 1) + (-3.0_wp*x20 + 3.0_wp*x21 + x22*x23 + x24*x25 - x24*x26)
            t_pd3_rrr_001 = d_a(2)*x27 - d_a(2)*x28 + d_a(2)*x29 + x31
