            pd3_rrr(2, 1, 1) = pd3_rrr(2, 1, 1) + t_pd3_rrr_001
            t_pd3_rrr_002 = d_a(3)*x27 - d_a(3)*x28 + d_a(3)*x29 + x33
            pd3_rrr(1, 1, 3) = pd3_rrr(1, 1, 3) + t_pd3_rrr_002
            pd3_rrr(1, 3, 1) = pd3_rrr(1, 3, 1) + t_pd3_rrr_002
            pd3_rrr(3, 1, 1) = pd3_rrr(3, 1, 1) + t_pd3_rrr_002
            t_pd3_rrr_011 = x2*x35 + x23*x37 - x36*x37 + x38
            pd3_rrr(1, 2, 2) = pd3_rrr(1, 2, 2) + t_pd3_rrr_011
            pd3_rrr(2, 1, 2) = pd3_rrr(2, 1, 2) + t_pd3_rrr_011
            pd3_rrr(2, 2, 1) = pd3_rrr(2, 2, 1) + t_pd3_rrr_011
            t_pd3_rrr_012 = x23*x40 + x35*x39 - x36*x40
            pd3_rrr(1, 2, 3) = pd3_rrr(1, 2, 3) + t_pd3_rrr_012
            pd3_rrr(1, 3, 2) = pd3_rrr(1, 3, 2) + t_pd3_rrr_012
            pd3_rrr(2, 1, 3) = pd3_rrr(2, 1, 3) + t_pd3_rrr_012
            pd3_rrr(2, 3, 1) = pd3_rrr(2, 3, 1) + t_pd3_rrr_012
            pd3_rrr(3, 1, 2) = pd3_rrr(3, 1, 2) + t_pd3_rrr_012
            pd3_rrr(3, 2, 1) = pd3_rrr(3, 2, 1) + t_pd3_rrr_012
