            pd4_rrrr(2, 2, 3, 2) = pd4_rrrr(2, 2, 3, 2) + t_pd4_rrrr_1112
            pd4_rrrr(2, 3, 2, 2) = pd4_rrrr(2, 3, 2, 2) + t_pd4_rrrr_1112
            pd4_rrrr(3, 2, 2, 2) = pd4_rrrr(3, 2, 2, 2) + t_pd4_rrrr_1112
            t_pd4_rrrr_1122 = x100*x76 - x100*x79 - x100*x80 + x100*x81 + x15 + x82 + x84 + x88
            pd4_rrrr(2, 2, 3, 3) = pd4_rrrr(2, 2, 3, 3) + t_pd4_rrrr_1122
            pd4_rrrr(2, 3, 2, 3) = pd4_rrrr(2, 3, 2, 3) + t_pd4_rrrr_1122
            pd4_rrrr(2, 3, 3, 2) = pd4_rrrr(2, 3, 3, 2) + t_pd4_rrrr_1122
            pd4_rrrr(3, 2, 2, 3) = pd4_rrrr(3, 2, 2, 3) + t_pd4_rrrr_1122
            pd4_rrrr(3, 2, 3, 2) = pd4_rrrr(3, 2, 3, 2) + t_pd4_rrrr_1122
            pd4_rrrr(3, 3, 2, 2) = pd4_rrrr(3, 3, 2, 2) + t_pd4_rrrr_1122
            t_pd4_rrrr_1222 = x101*x76 - x101*x79 - x101*x80 + x101*x81 + x99
            pd4_rrrr(2, 3, 3, 3) = pd4_rrrr(2, 3, 3, 3) + t_pd4_rrrr_1222
            pd4_rrrr(3, 2, 3, 3) = pd4_rrrr(3, 2, 3, 3) + t_pd4_rrrr_1222
            pd4_rrrr(3, 3, 2, 3) = pd4_rrrr(3, 3, 2, 3) + t_pd4_rrrr_1222
            pd4_rrrr(3, 3, 3, 2) = pd4_rrrr(3, 3, 3, 2) + t_pd4_rrrr_1222
            pd4_rrrr(3, 3, 3, 3) = &
               pd4_rrrr(3, 3, 3, 3) + (x102*x76 - x102*x80 + x103*x23 - x103*x28 - x104*x60 + &
               x104*x62 + 6.0_wp*x48 + x63)
         end block
      end select

   end subroutine cfc_atomic_term_eval

   !> Accumulate one pair's contribution to PD, split by displacement vector.
   !>
   !> Computes ``c (1 - vec(s_a).vec(s_b))**m exp(a2 (s_a + s_b - 2))`` with
   !> ``m = 4`` baked into the symbolic differentiation, and accumulates the
   !> value together with every partial derivative taken separately with
   !> respect to ``d_a = r - r_a`` and ``d_b = r - r_b``, up to total order
   !> 4.
   !>
   !> Spatial and nuclear derivatives follow from the splits.  With
   !> ``d/dr = d/d(d_a) + d/d(d_b)`` and ``d/dr_A = -d/d(d_A)``:
   !>
   !>    dK/dr_i             = pd1_a_i + pd1_b_i
   !>    d2K/dr_i dr_j       = pd2_aa_ij + pd2_ab_ij + pd2_ab_ji + pd2_bb_ij
   !>    d3K/dr_i dr_j dr_k  = pd3_aaa + sym(pd3_aab) + sym(pd3_abb) + pd3_bbb
   !>    d4K/dr^4            = pd4_aaaa + sym(pd4_aaab) + sym(pd4_aabb)
   !>                          + sym(pd4_abbb) + pd4_bbbb
   !>
   !> where ``sym`` sums the distinct index assignments of the spatial indices
   !> to the a/b slots (4 for aaab and abbb, 6 for aabb, 3 for aab and abb).
   !> Nuclear derivatives pick up one minus sign per nuclear index.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    d_b        Displacement r - r_b
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    R_b        Radius of atom b
   !> @param[in]    a2         Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
   !> @param[in]    c_par      Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
   !> @param[in]    max_deriv  Maximum derivative order to accumulate (0..4); a larger value is
   !>                          treated as 4
   !> @param[inout] pd0        Pseudo-density value accumulator
   !> @param[inout] pd1_a      d^1 K / d(d_a)^1 d(d_b)^0 accumulator (no index symmetry)
   !> @param[inout] pd1_b      d^1 K / d(d_a)^0 d(d_b)^1 accumulator (no index symmetry)
   !> @param[inout] pd2_aa     d^2 K / d(d_a)^2 d(d_b)^0 accumulator (symmetric in the first 2
   !>                          indices)
   !> @param[inout] pd2_ab     d^2 K / d(d_a)^1 d(d_b)^1 accumulator (no index symmetry)
   !> @param[inout] pd2_bb     d^2 K / d(d_a)^0 d(d_b)^2 accumulator (symmetric in the last 2
   !>                          indices)
   !> @param[inout] pd3_aaa    d^3 K / d(d_a)^3 d(d_b)^0 accumulator (symmetric in the first 3
   !>                          indices)
   !> @param[inout] pd3_aab    d^3 K / d(d_a)^2 d(d_b)^1 accumulator (symmetric in the first 2
   !>                          indices)
   !> @param[inout] pd3_abb    d^3 K / d(d_a)^1 d(d_b)^2 accumulator (symmetric in the last 2
   !>                          indices)
   !> @param[inout] pd3_bbb    d^3 K / d(d_a)^0 d(d_b)^3 accumulator (symmetric in the last 3
   !>                          indices)
   !> @param[inout] pd4_aaaa   d^4 K / d(d_a)^4 d(d_b)^0 accumulator (symmetric in the first 4
   !>                          indices)
   !> @param[inout] pd4_aaab   d^4 K / d(d_a)^3 d(d_b)^1 accumulator (symmetric in the first 3
   !>                          indices)
   !> @param[inout] pd4_aabb   d^4 K / d(d_a)^2 d(d_b)^2 accumulator (symmetric within each index
   !>                          group)
   !> @param[inout] pd4_abbb   d^4 K / d(d_a)^1 d(d_b)^3 accumulator (symmetric in the last 3
   !>                          indices)
   !> @param[inout] pd4_bbbb   d^4 K / d(d_a)^0 d(d_b)^4 accumulator (symmetric in the last 4
   !>                          indices)
   pure subroutine cfc_pair_term_eval(d_a, d_b, R_a, R_b, a2, c_par, max_deriv, pd0, pd1_a, &
                                      pd1_b, pd2_aa, pd2_ab, pd2_bb, pd3_aaa, pd3_aab, pd3_abb, &
                                      pd3_bbb, pd4_aaaa, pd4_aaab, pd4_aabb, pd4_abbb, pd4_bbbb)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Maximum derivative order to accumulate (0..4); a larger value is treated as 4
      integer, intent(in) :: max_deriv
      !> Pseudo-density value accumulator
      real(wp), intent(inout) :: pd0
      !> d^1 K / d(d_a)^1 d(d_b)^0 accumulator (no index symmetry)
      real(wp), intent(inout) :: pd1_a(3)
      !> d^1 K / d(d_a)^0 d(d_b)^1 accumulator (no index symmetry)
      real(wp), intent(inout) :: pd1_b(3)
      !> d^2 K / d(d_a)^2 d(d_b)^0 accumulator (symmetric in the first 2 indices)
      real(wp), intent(inout) :: pd2_aa(3, 3)
      !> d^2 K / d(d_a)^1 d(d_b)^1 accumulator (no index symmetry)
      real(wp), intent(inout) :: pd2_ab(3, 3)
      !> d^2 K / d(d_a)^0 d(d_b)^2 accumulator (symmetric in the last 2 indices)
      real(wp), intent(inout) :: pd2_bb(3, 3)
      !> d^3 K / d(d_a)^3 d(d_b)^0 accumulator (symmetric in the first 3 indices)
      real(wp), intent(inout) :: pd3_aaa(3, 3, 3)
      !> d^3 K / d(d_a)^2 d(d_b)^1 accumulator (symmetric in the first 2 indices)
      real(wp), intent(inout) :: pd3_aab(3, 3, 3)
      !> d^3 K / d(d_a)^1 d(d_b)^2 accumulator (symmetric in the last 2 indices)
      real(wp), intent(inout) :: pd3_abb(3, 3, 3)
      !> d^3 K / d(d_a)^0 d(d_b)^3 accumulator (symmetric in the last 3 indices)
      real(wp), intent(inout) :: pd3_bbb(3, 3, 3)
      !> d^4 K / d(d_a)^4 d(d_b)^0 accumulator (symmetric in the first 4 indices)
      real(wp), intent(inout) :: pd4_aaaa(3, 3, 3, 3)
      !> d^4 K / d(d_a)^3 d(d_b)^1 accumulator (symmetric in the first 3 indices)
      real(wp), intent(inout) :: pd4_aaab(3, 3, 3, 3)
      !> d^4 K / d(d_a)^2 d(d_b)^2 accumulator (symmetric within each index group)
      real(wp), intent(inout) :: pd4_aabb(3, 3, 3, 3)
      !> d^4 K / d(d_a)^1 d(d_b)^3 accumulator (symmetric in the last 3 indices)
      real(wp), intent(inout) :: pd4_abbb(3, 3, 3, 3)
      !> d^4 K / d(d_a)^0 d(d_b)^4 accumulator (symmetric in the last 4 indices)
      real(wp), intent(inout) :: pd4_bbbb(3, 3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            pd0 = &
               pd0 + (c_par*((-x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + &
               1.0_wp)*(-x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + &
               1.0_wp)*(-x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + &
               1.0_wp)*(-x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + &
               1.0_wp))*exp(a2*(x0*sqrt((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))) + &
               x1*sqrt((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))) - 2.0_wp)))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = x0*x1
            x3 = -x2*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + 1.0_wp
            x4 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x5 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x6 = c_par*exp(a2*(x0*x4 + x1*x5 - 2.0_wp))
            x7 = (x3*x3*x3*x3)*x6
            x8 = 4.0_wp*x2*(x3*x3*x3)*x6
            x9 = a2*x7
            x10 = x0*x9/x4
            x11 = x1*x9/x5
            pd0 = pd0 + (x7)
            pd1_a(1) = pd1_a(1) + (d_a(1)*x10 - d_b(1)*x8)
            pd1_a(2) = pd1_a(2) + (d_a(2)*x10 - d_b(2)*x8)
            pd1_a(3) = pd1_a(3) + (d_a(3)*x10 - d_b(3)*x8)
            pd1_b(1) = pd1_b(1) + (-d_a(1)*x8 + d_b(1)*x11)
            pd1_b(2) = pd1_b(2) + (-d_a(2)*x8 + d_b(2)*x11)
            pd1_b(3) = pd1_b(3) + (-d_a(3)*x8 + d_b(3)*x11)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, t_pd2_aa_01, t_pd2_aa_02, t_pd2_aa_12, t_pd2_bb_01
            real(wp) :: t_pd2_bb_02, t_pd2_bb_12

            x0 = d_a(1)*d_b(1)
            x1 = d_a(2)*d_b(2)
            x2 = d_a(3)*d_b(3)
            x3 = 1.0_wp/R_a
            x4 = 1.0_wp/R_b
            x5 = x3*x4
            x6 = -x5*(x0 + x1 + x2) + 1.0_wp
            x7 = (x6*x6*x6*x6)
            x8 = (d_a(1)*d_a(1))
            x9 = (d_a(2)*d_a(2))
            x10 = (d_a(3)*d_a(3))
            x11 = x10 + x8 + x9
            x12 = sqrt(x11)
            x13 = (d_b(1)*d_b(1))
            x14 = (d_b(2)*d_b(2))
            x15 = (d_b(3)*d_b(3))
            x16 = x13 + x14 + x15
            x17 = sqrt(x16)
            x18 = exp(a2*(x12*x3 + x17*x4 - 2.0_wp))
            x19 = c_par*x18
            x20 = x19*x7
            x21 = x19*(x6*x6*x6)
            x22 = 4.0_wp*x21
            x23 = x22*x5
            x24 = 1.0_wp/x12
            x25 = a2*x20
            x26 = x25*x3
            x27 = x24*x26
            x28 = 1.0_wp/x17
            x29 = x25*x4
            x30 = x28*x29
            x31 = 1.0_wp/(R_b*R_b)
            x32 = x13*x31
            x33 = 1.0_wp/(R_a*R_a)
            x34 = (x6*x6)
            x35 = 12.0_wp*x19*x33*x34
            x36 = x26/(x11*sqrt(x11))
            x37 = x33*x8
            x38 = 1.0_wp/x11
            x39 = (a2*a2)
            x40 = x20*x39
            x41 = x38*x40
            x42 = 8.0_wp*a2*x21
            x43 = x0*x42
            x44 = x24*x4
            x45 = x33*x44
            x46 = d_a(1)*d_a(2)
            x47 = a2*x22
            x48 = x44*x47
            x49 = x33*x48
            x50 = d_a(1)*x49
            x51 = d_b(1)*x49
            x52 = d_a(1)*d_a(3)
            x53 = x31*x35
            x54 = x33*x41
            x55 = x42*x45
            x56 = d_a(2)*d_a(3)
            x57 = d_a(2)*d_b(3)
            x58 = d_a(3)*d_b(2)
            x59 = x28*x3
            x60 = x47*x59
            x61 = d_b(1)*x53
            x62 = x24*x28*x40*x5
            x63 = d_a(1)*x62
            x64 = d_b(1)*d_b(2)
            x65 = x31*x60
            x66 = -x46*x49 - x64*x65
            x67 = d_b(1)*d_b(3)
            x68 = -x49*x52 - x65*x67
            x69 = d_b(2)*x53
            x70 = d_b(1)*x62
            x71 = d_b(2)*d_b(3)
            x72 = -x49*x56 - x65*x71
            x73 = d_b(3)*x53
            x74 = x29/(x16*sqrt(x16))
            x75 = 1.0_wp/x16
            x76 = x40*x75
            x77 = x31*x59
            x78 = d_a(1)*x65
            x79 = d_b(1)*x65
            x80 = x31*x76
            x81 = x42*x77
            pd0 = pd0 + (x20)
            pd1_a(1) = pd1_a(1) + (d_a(1)*x27 - d_b(1)*x23)
            pd1_a(2) = pd1_a(2) + (d_a(2)*x27 - d_b(2)*x23)
            pd1_a(3) = pd1_a(3) + (d_a(3)*x27 - d_b(3)*x23)
            pd1_b(1) = pd1_b(1) + (-d_a(1)*x23 + d_b(1)*x30)
            pd1_b(2) = pd1_b(2) + (-d_a(2)*x23 + d_b(2)*x30)
            pd1_b(3) = pd1_b(3) + (-d_a(3)*x23 + d_b(3)*x30)
            pd2_aa(1, 1) = pd2_aa(1, 1) + (x27 + x32*x35 - x36*x8 + x37*x41 - x43*x45)
            t_pd2_aa_01 = &
               c_par*d_a(1)*d_a(2)*x18*x33*x38*x39*x7 + &
               12.0_wp*c_par*d_b(1)*d_b(2)*x18*x31*x33*x34 - d_a(2)*x51 - d_b(2)*x50 - x36*x46
            pd2_aa(1, 2) = pd2_aa(1, 2) + t_pd2_aa_01
            pd2_aa(2, 1) = pd2_aa(2, 1) + t_pd2_aa_01
            t_pd2_aa_02 = &
               c_par*d_a(1)*d_a(3)*x18*x33*x38*x39*x7 + &
               12.0_wp*c_par*d_b(1)*d_b(3)*x18*x31*x33*x34 - d_a(3)*x51 - d_b(3)*x50 - x36*x52
            pd2_aa(1, 3) = pd2_aa(1, 3) + t_pd2_aa_02
            pd2_aa(3, 1) = pd2_aa(3, 1) + t_pd2_aa_02
            pd2_aa(2, 2) = pd2_aa(2, 2) + (-x1*x55 + x14*x53 + x27 - x36*x9 + x54*x9)
            t_pd2_aa_12 = &
               c_par*d_a(2)*d_a(3)*x18*x33*x38*x39*x7 + &
               12.0_wp*c_par*d_b(2)*d_b(3)*x18*x31*x33*x34 - x36*x56 - x49*x57 - x49*x58
            pd2_aa(2, 3) = pd2_aa(2, 3) + t_pd2_aa_12
            pd2_aa(3, 2) = pd2_aa(3, 2) + t_pd2_aa_12
            pd2_aa(3, 3) = pd2_aa(3, 3) + (-x10*x36 + x10*x54 + x15*x53 - x2*x55 + x27)
            pd2_ab(1, 1) = &
               pd2_ab(1, 1) + (c_par*d_a(1)*d_b(1)*x18*x24*x28*x3*x39*x4*x7 + &
               12.0_wp*c_par*d_a(1)*d_b(1)*x18*x31*x33*x34 - x23 - x32*x60 - x37*x48)
            pd2_ab(1, 2) = pd2_ab(1, 2) + (d_a(2)*x61 + d_b(2)*x63 + x66)
            pd2_ab(1, 3) = pd2_ab(1, 3) + (d_a(3)*x61 + d_b(3)*x63 + x68)
            pd2_ab(2, 1) = pd2_ab(2, 1) + (d_a(1)*x69 + d_a(2)*x70 + x66)
            pd2_ab(2, 2) = &
               pd2_ab(2, 2) + (c_par*d_a(2)*d_b(2)*x18*x24*x28*x3*x39*x4*x7 + &
               12.0_wp*c_par*d_a(2)*d_b(2)*x18*x31*x33*x34 - x14*x65 - x23 - x49*x9)
            pd2_ab(2, 3) = pd2_ab(2, 3) + (d_a(3)*x69 + x57*x62 + x72)
            pd2_ab(3, 1) = pd2_ab(3, 1) + (d_a(1)*x73 + d_a(3)*x70 + x68)
            pd2_ab(3, 2) = pd2_ab(3, 2) + (d_a(2)*x73 + x58*x62 + x72)
            pd2_ab(3, 3) = &
               pd2_ab(3, 3) + (c_par*d_a(3)*d_b(3)*x18*x24*x28*x3*x39*x4*x7 + &
               12.0_wp*c_par*d_a(3)*d_b(3)*x18*x31*x33*x34 - x10*x49 - x15*x65 - x23)
            pd2_bb(1, 1) = pd2_bb(1, 1) + (-x13*x74 + x30 + x32*x76 - x43*x77 + x53*x8)
            t_pd2_bb_01 = &
               12.0_wp*c_par*d_a(1)*d_a(2)*x18*x31*x33*x34 + &
               c_par*d_b(1)*d_b(2)*x18*x31*x39*x7*x75 - d_a(2)*x79 - d_b(2)*x78 - x64*x74
            pd2_bb(1, 2) = pd2_bb(1, 2) + t_pd2_bb_01
            pd2_bb(2, 1) = pd2_bb(2, 1) + t_pd2_bb_01
            t_pd2_bb_02 = &
               12.0_wp*c_par*d_a(1)*d_a(3)*x18*x31*x33*x34 + &
               c_par*d_b(1)*d_b(3)*x18*x31*x39*x7*x75 - d_a(3)*x79 - d_b(3)*x78 - x67*x74
            pd2_bb(1, 3) = pd2_bb(1, 3) + t_pd2_bb_02
            pd2_bb(3, 1) = pd2_bb(3, 1) + t_pd2_bb_02
            pd2_bb(2, 2) = pd2_bb(2, 2) + (-x1*x81 - x14*x74 + x14*x80 + x30 + x53*x9)
            t_pd2_bb_12 = &
               12.0_wp*c_par*d_a(2)*d_a(3)*x18*x31*x33*x34 + &
               c_par*d_b(2)*d_b(3)*x18*x31*x39*x7*x75 - x57*x65 - x58*x65 - x71*x74
