            hvp2_rr_a(2, 3, 1) = hvp2_rr_a(2, 3, 1) + t_hvp2_rr_a_120
            hvp2_rr_a(3, 2, 1) = hvp2_rr_a(3, 2, 1) + t_hvp2_rr_a_120
            t_hvp2_rr_a_121 = x138
            hvp2_rr_a(2, 3, 2) = hvp2_rr_a(2, 3, 2) + t_hvp2_rr_a_121
            hvp2_rr_a(3, 2, 2) = hvp2_rr_a(3, 2, 2) + t_hvp2_rr_a_121
            t_hvp2_rr_a_122 = x141
            hvp2_rr_a(2, 3, 3) = hvp2_rr_a(2, 3, 3) + t_hvp2_rr_a_122
            hvp2_rr_a(3, 2, 3) = hvp2_rr_a(3, 2, 3) + t_hvp2_rr_a_122
            hvp2_rr_a(3, 3, 1) = hvp2_rr_a(3, 3, 1) + (x127)
            hvp2_rr_a(3, 3, 2) = hvp2_rr_a(3, 3, 2) + (x141)
            hvp2_rr_a(3, 3, 3) = hvp2_rr_a(3, 3, 3) + (x145)
         end block
      end select

   end subroutine cfc_atomic_hvp_eval

   !> Accumulate a nuclear Hessian-vector product, plus the tangent ladder.
   !>
   !> Given one displacement direction per atom, this returns, for each center
   !> A of this pair,
   !>
   !>    hvp{k}_A(i1..ik, beta) = sum_B sum_alpha v_B,alpha
   !>                               d^2/(dr_A,beta dr_B,alpha)
   !>                               d^k K / dr_i1..dr_ik
   !>
   !> i.e. exactly one of the two nuclear indices is contracted, the other is
   !> retained as the trailing array index.  The caller scatters the ``_a`` and
   !> ``_b`` blocks into the columns of its per-atom result, turning what would
   !> be an O(n**2) tensor into O(n) storage.  Signs are already applied (the
   !> two nuclear sign flips cancel).
   !>
   !> The `tg*` accumulators of `*_tangent_eval` are filled as well.  They cost
   !> nothing: the two ladders share almost all of their derivative structure,
   !> and CSE'd together the top branch needs 1752 temporaries against 3298 for
   !> the two computed apart.  CALL EITHER THIS ROUTINE OR `*_tangent_eval` FOR
   !> A GIVEN PAIR, NEVER BOTH -- the tangent contribution would be counted
   !> twice.  The HVP ladder stops at spatial order 2 (its total order is one
   !> higher than the tangent's); the tangent ladder runs to 3.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    d_b        Displacement r - r_b
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    R_b        Radius of atom b
   !> @param[in]    a2         Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
   !> @param[in]    c_par      Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
   !> @param[in]    v_a        Nuclear displacement direction of atom a
   !> @param[in]    v_b        Nuclear displacement direction of atom b
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..3); a larger value
   !>                          is treated as 3
   !> @param[inout] tg0        sum_A v_A . d/dr_A of the order-0 spatial derivative (free by-product
   !>                          of the HVP; see the note above)
   !> @param[inout] tg1_r      sum_A v_A . d/dr_A of the order-1 spatial derivative (free by-product
   !>                          of the HVP; see the note above)
   !> @param[inout] tg2_rr     sum_A v_A . d/dr_A of the order-2 spatial derivative (free by-product
   !>                          of the HVP; see the note above)
   !> @param[inout] tg3_rrr    sum_A v_A . d/dr_A of the order-3 spatial derivative (free by-product
   !>                          of the HVP; see the note above)
   !> @param[inout] hvp0_a     sum_B v_B . d2/(dr_a dr_B) of the order-0 spatial derivative;
   !>                          trailing index is the retained nuclear component of atom a
   !> @param[inout] hvp0_b     sum_B v_B . d2/(dr_b dr_B) of the order-0 spatial derivative;
   !>                          trailing index is the retained nuclear component of atom b
   !> @param[inout] hvp1_r_a   sum_B v_B . d2/(dr_a dr_B) of the order-1 spatial derivative;
   !>                          trailing index is the retained nuclear component of atom a
   !> @param[inout] hvp1_r_b   sum_B v_B . d2/(dr_b dr_B) of the order-1 spatial derivative;
   !>                          trailing index is the retained nuclear component of atom b
   !> @param[inout] hvp2_rr_a  sum_B v_B . d2/(dr_a dr_B) of the order-2 spatial derivative;
   !>                          trailing index is the retained nuclear component of atom a
   !> @param[inout] hvp2_rr_b  sum_B v_B . d2/(dr_b dr_B) of the order-2 spatial derivative;
   !>                          trailing index is the retained nuclear component of atom b
   pure subroutine cfc_pair_hvp_eval(d_a, d_b, R_a, R_b, a2, c_par, v_a, v_b, max_deriv, tg0, &
                                     tg1_r, tg2_rr, tg3_rrr, hvp0_a, hvp0_b, hvp1_r_a, hvp1_r_b, &
                                     hvp2_rr_a, hvp2_rr_b)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Nuclear displacement direction of atom a
      real(wp), intent(in) :: v_a(3)
      !> Nuclear displacement direction of atom b
      real(wp), intent(in) :: v_b(3)
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A v_A . d/dr_A of the order-0 spatial derivative (free by-product of the HVP; see the
      !> note above)
      real(wp), intent(inout) :: tg0
      !> sum_A v_A . d/dr_A of the order-1 spatial derivative (free by-product of the HVP; see the
      !> note above)
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A v_A . d/dr_A of the order-2 spatial derivative (free by-product of the HVP; see the
      !> note above)
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A v_A . d/dr_A of the order-3 spatial derivative (free by-product of the HVP; see the
      !> note above)
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)
      !> sum_B v_B . d2/(dr_a dr_B) of the order-0 spatial derivative; trailing index is the
      !> retained nuclear component of atom a
      real(wp), intent(inout) :: hvp0_a(3)
      !> sum_B v_B . d2/(dr_b dr_B) of the order-0 spatial derivative; trailing index is the
      !> retained nuclear component of atom b
      real(wp), intent(inout) :: hvp0_b(3)
      !> sum_B v_B . d2/(dr_a dr_B) of the order-1 spatial derivative; trailing index is the
      !> retained nuclear component of atom a
      real(wp), intent(inout) :: hvp1_r_a(3, 3)
      !> sum_B v_B . d2/(dr_b dr_B) of the order-1 spatial derivative; trailing index is the
      !> retained nuclear component of atom b
      real(wp), intent(inout) :: hvp1_r_b(3, 3)
      !> sum_B v_B . d2/(dr_a dr_B) of the order-2 spatial derivative; trailing index is the
      !> retained nuclear component of atom a
      real(wp), intent(inout) :: hvp2_rr_a(3, 3, 3)
      !> sum_B v_B . d2/(dr_b dr_B) of the order-2 spatial derivative; trailing index is the
      !> retained nuclear component of atom b
      real(wp), intent(inout) :: hvp2_rr_b(3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93, x94, x95, x96

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = x0*x1
            x3 = d_a(1)*d_b(1)
            x4 = d_a(2)*d_b(2)
            x5 = d_a(3)*d_b(3)
            x6 = -x2*(x3 + x4 + x5) + 1.0_wp
            x7 = (d_a(1)*d_a(1))
            x8 = (d_a(2)*d_a(2))
            x9 = (d_a(3)*d_a(3))
            x10 = x7 + x8 + x9
            x11 = sqrt(x10)
            x12 = (d_b(1)*d_b(1))
            x13 = (d_b(2)*d_b(2))
            x14 = (d_b(3)*d_b(3))
            x15 = x12 + x13 + x14
            x16 = sqrt(x15)
            x17 = exp(a2*(x0*x11 + x1*x16 - 2.0_wp))
            x18 = c_par*x17
            x19 = x18*(x6*x6*x6)
            x20 = 4.0_wp*x19
            x21 = x2*x20
            x22 = 1.0_wp/x11
            x23 = (x6*x6*x6*x6)
            x24 = x18*x23
            x25 = a2*x24
            x26 = x0*x25
            x27 = x22*x26
            x28 = 1.0_wp/x16
            x29 = x1*x25
            x30 = x28*x29
            x31 = 1.0_wp/(R_b*R_b)
            x32 = 1.0_wp/(R_a*R_a)
            x33 = (x6*x6)
            x34 = 12.0_wp*x18*x32*x33
            x35 = x31*x34
            x36 = d_b(1)*x35
            x37 = (a2*a2)
            x38 = x24*x37
            x39 = x2*x22*x28*x38
            x40 = d_a(1)*x39
            x41 = d_a(1)*d_a(2)
            x42 = a2*x20
            x43 = x1*x22
            x44 = x42*x43
            x45 = x32*x44
            x46 = d_b(1)*d_b(2)
            x47 = x0*x28
            x48 = x42*x47
            x49 = x31*x48
            x50 = -x41*x45 - x46*x49
            x51 = d_a(2)*x36 + d_b(2)*x40 + x50
            x52 = d_a(1)*d_a(3)
            x53 = d_b(1)*d_b(3)
            x54 = -x45*x52 - x49*x53
            x55 = d_a(3)*x36 + d_b(3)*x40 + x54
            x56 = x12*x31
            x57 = x26/(x10*sqrt(x10))
            x58 = x32*x7
            x59 = 1.0_wp/x10
            x60 = x38*x59
            x61 = 8.0_wp*a2*x19
            x62 = x3*x61
            x63 = x32*x43
            x64 = d_a(1)*x45
            x65 = d_b(1)*x45
            x66 = &
               c_par*d_a(1)*d_a(2)*x17*x23*x32*x37*x59 + &
               12.0_wp*c_par*d_b(1)*d_b(2)*x17*x31*x32*x33 - d_a(2)*x65 - d_b(2)*x64 - x41*x57
            x67 = &
               c_par*d_a(1)*d_a(3)*x17*x23*x32*x37*x59 + &
               12.0_wp*c_par*d_b(1)*d_b(3)*x17*x31*x32*x33 - d_a(3)*x65 - d_b(3)*x64 - x52*x57
            x68 = &
               c_par*d_a(1)*d_b(1)*x0*x1*x17*x22*x23*x28*x37 + &
               12.0_wp*c_par*d_a(1)*d_b(1)*x17*x31*x32*x33 - x21 - x44*x58 - x48*x56
            x69 = d_b(2)*x35
            x70 = d_b(1)*x39
            x71 = d_a(1)*x69 + d_a(2)*x70 + x50
            x72 = d_a(2)*d_b(3)
            x73 = d_a(2)*d_a(3)
            x74 = d_b(2)*d_b(3)
            x75 = -x45*x73 - x49*x74
            x76 = d_a(3)*x69 + x39*x72 + x75
            x77 = x32*x60
            x78 = x61*x63
            x79 = d_a(3)*d_b(2)
            x80 = &
               c_par*d_a(2)*d_a(3)*x17*x23*x32*x37*x59 + &
               12.0_wp*c_par*d_b(2)*d_b(3)*x17*x31*x32*x33 - x45*x72 - x45*x79 - x57*x73
            x81 = &
               c_par*d_a(2)*d_b(2)*x0*x1*x17*x22*x23*x28*x37 + &
               12.0_wp*c_par*d_a(2)*d_b(2)*x17*x31*x32*x33 - x13*x49 - x21 - x45*x8
            x82 = d_b(3)*x35
            x83 = d_a(1)*x82 + d_a(3)*x70 + x54
            x84 = d_a(2)*x82 + x39*x79 + x75
            x85 = &
               c_par*d_a(3)*d_b(3)*x0*x1*x17*x22*x23*x28*x37 + &
               12.0_wp*c_par*d_a(3)*d_b(3)*x17*x31*x32*x33 - x14*x49 - x21 - x45*x9
            x86 = x29/(x15*sqrt(x15))
            x87 = 1.0_wp/x15
            x88 = x38*x87
            x89 = x31*x47
            x90 = d_a(1)*x49
            x91 = d_b(1)*x49
            x92 = &
               12.0_wp*c_par*d_a(1)*d_a(2)*x17*x31*x32*x33 + &
               c_par*d_b(1)*d_b(2)*x17*x23*x31*x37*x87 - d_a(2)*x91 - d_b(2)*x90 - x46*x86
            x93 = &
               12.0_wp*c_par*d_a(1)*d_a(3)*x17*x31*x32*x33 + &
               c_par*d_b(1)*d_b(3)*x17*x23*x31*x37*x87 - d_a(3)*x91 - d_b(3)*x90 - x53*x86
            x94 = x31*x88
            x95 = x61*x89
            x96 = &
               12.0_wp*c_par*d_a(2)*d_a(3)*x17*x31*x32*x33 + &
               c_par*d_b(2)*d_b(3)*x17*x23*x31*x37*x87 - x49*x72 - x49*x79 - x74*x86
            tg0 = &
               tg0 + (-v_a(1)*(d_a(1)*x27 - d_b(1)*x21) - v_a(2)*(d_a(2)*x27 - d_b(2)*x21) - &
               v_a(3)*(d_a(3)*x27 - d_b(3)*x21) - v_b(1)*(-d_a(1)*x21 + d_b(1)*x30) - &
               v_b(2)*(-d_a(2)*x21 + d_b(2)*x30) - v_b(3)*(-d_a(3)*x21 + d_b(3)*x30))
            hvp0_a(1) = &
               hvp0_a(1) + (v_a(1)*(x27 + x34*x56 - x57*x7 + x58*x60 - x62*x63) + v_a(2)*x66 + &
               v_a(3)*x67 + v_b(1)*x68 + v_b(2)*x51 + v_b(3)*x55)
            hvp0_a(2) = &
               hvp0_a(2) + (v_a(1)*x66 + v_a(2)*(x13*x35 + x27 - x4*x78 - x57*x8 + x77*x8) + &
               v_a(3)*x80 + v_b(1)*x71 + v_b(2)*x81 + v_b(3)*x76)
            hvp0_a(3) = &
               hvp0_a(3) + (v_a(1)*x67 + v_a(2)*x80 + v_a(3)*(x14*x35 + x27 - x5*x78 - x57*x9 + &
               x77*x9) + v_b(1)*x83 + v_b(2)*x84 + v_b(3)*x85)
            hvp0_b(1) = &
               hvp0_b(1) + (v_a(1)*x68 + v_a(2)*x71 + v_a(3)*x83 + v_b(1)*(-x12*x86 + x30 + x35*x7 &
               + x56*x88 - x62*x89) + v_b(2)*x92 + v_b(3)*x93)
            hvp0_b(2) = &
               hvp0_b(2) + (v_a(1)*x51 + v_a(2)*x81 + v_a(3)*x84 + v_b(1)*x92 + v_b(2)*(-x13*x86 + &
               x13*x94 + x30 + x35*x8 - x4*x95) + v_b(3)*x96)
            hvp0_b(3) = &
               hvp0_b(3) + (v_a(1)*x55 + v_a(2)*x76 + v_a(3)*x85 + v_b(1)*x93 + v_b(2)*x96 + &
               v_b(3)*(-x14*x86 + x14*x94 + x30 + x35*x9 - x5*x95))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93, x94, x95, x96, x97, x98, x99, x100, x101, x102, x103, x104, x105
            real(wp) :: x106, x107, x108, x109, x110, x111, x112, x113, x114, x115, x116, x117, x118
            real(wp) :: x119, x120, x121, x122, x123, x124, x125, x126, x127, x128, x129, x130, x131
            real(wp) :: x132, x133, x134, x135, x136, x137, x138, x139, x140, x141, x142, x143, x144
            real(wp) :: x145, x146, x147, x148, x149, x150, x151, x152, x153, x154, x155, x156, x157
            real(wp) :: x158, x159, x160, x161, x162, x163, x164, x165, x166, x167, x168, x169, x170
            real(wp) :: x171, x172, x173, x174, x175, x176, x177, x178, x179, x180, x181, x182, x183
            real(wp) :: x184, x185, x186, x187, x188, x189, x190, x191, x192, x193, x194, x195, x196
            real(wp) :: x197, x198, x199, x200, x201, x202, x203, x204, x205, x206, x207, x208, x209
            real(wp) :: x210, x211, x212, x213, x214, x215, x216, x217, x218, x219, x220, x221, x222
            real(wp) :: x223, x224, x225, x226, x227, x228, x229, x230, x231, x232, x233, x234, x235
            real(wp) :: x236, x237, x238, x239, x240, x241, x242, x243, x244, x245, x246, x247, x248
            real(wp) :: x249, x250, x251, x252, x253, x254, x255, x256, x257, x258, x259, x260, x261
            real(wp) :: x262, x263, x264, x265, x266, x267, x268, x269, x270, x271, x272, x273, x274
            real(wp) :: x275, x276, x277, x278, x279, x280, x281, x282, x283, x284, x285, x286, x287
            real(wp) :: x288, x289, x290, x291, x292, x293, x294, x295, x296, x297, x298, x299, x300
            real(wp) :: x301, x302, x303, x304, x305, x306, x307, x308, x309, x310, x311, x312, x313
            real(wp) :: x314, x315, x316, x317, x318, x319, x320, x321, x322, x323, x324, x325, x326
            real(wp) :: x327, x328, x329, x330, x331, x332, x333, x334, x335, x336, x337, x338, x339
            real(wp) :: x340, x341, x342, x343, x344, x345, x346, x347, x348, x349, x350, x351, x352
            real(wp) :: x353, x354, x355, x356, x357, x358, x359, x360, x361, x362, x363, x364, x365
            real(wp) :: x366, x367, x368, x369, x370, x371, x372, x373, x374, x375, x376, x377, x378
            real(wp) :: x379, x380, x381, x382, x383, x384, x385, x386, x387, x388, x389, x390, x391
            real(wp) :: x392, x393, x394, x395, x396, x397, x398, x399, x400, x401, x402, x403, x404
            real(wp) :: x405, x406, x407, x408, x409, x410, x411, x412, x413, x414, x415, x416, x417
            real(wp) :: x418, x419, x420, x421, x422, x423, x424, x425, x426, x427, x428, x429, x430
            real(wp) :: x431, x432, x433, x434, x435, x436, x437, x438, x439, x440, x441, x442, x443
            real(wp) :: x444, x445, x446, x447, x448, x449, x450, x451, x452, x453, x454, x455, x456
            real(wp) :: x457, x458, x459, x460, x461, x462, x463, x464, x465, x466, x467, x468, x469
            real(wp) :: x470

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = x0*x1
            x3 = d_a(1)*d_b(1)
            x4 = d_a(2)*d_b(2)
            x5 = d_a(3)*d_b(3)
            x6 = -x2*(x3 + x4 + x5) + 1.0_wp
            x7 = (x6*x6*x6)
            x8 = (d_a(1)*d_a(1))
