   !> Accumulate the uncontracted nuclear derivative of the spatial derivatives.
   !>
   !> Given no direction vector, this returns, for each center A of this atom,
   !>
   !>    qn{k}_A(i1..ik, beta) = d/dr_A,beta  d^k K / dr_i1..dr_ik
   !>
   !> i.e. one nuclear index, kept.  Summed over an atom's own term and every
   !> pair it belongs to, this is the per-atom family `cfc_hvp_eval` needs (and
   !> the same object the uncontracted `f3_rr_rA` accessor is built from).
   !> Nuclear signs are already applied.
   !>
   !> A caller wanting nuclear derivatives wants the spatial ones too, and runs
   !> `*_spatial_eval` alongside this: the two are separate routines on purpose,
   !> see the note on the builder.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    a1         Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..3); a larger value
   !>                          is treated as 3
   !> @param[inout] qn0_a      d/dr_a of the order-0 spatial derivative; trailing index is the
   !>                          nuclear component of atom a
   !> @param[inout] qn1_r_a    d/dr_a of the order-1 spatial derivative; trailing index is the
   !>                          nuclear component of atom a
   !> @param[inout] qn2_rr_a   d/dr_a of the order-2 spatial derivative; trailing index is the
   !>                          nuclear component of atom a
   !> @param[inout] qn3_rrr_a  d/dr_a of the order-3 spatial derivative; trailing index is the
   !>                          nuclear component of atom a
   pure subroutine cfc_atomic_nuclear_eval(d_a, R_a, a1, max_deriv, qn0_a, qn1_r_a, qn2_rr_a, &
                                           qn3_rrr_a)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dr_a of the order-0 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn0_a(3)
      !> d/dr_a of the order-1 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn1_r_a(3, 3)
      !> d/dr_a of the order-2 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn2_rr_a(3, 3, 3)
      !> d/dr_a of the order-3 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn3_rrr_a(3, 3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2

            x0 = 1.0_wp/R_a
            x1 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x2 = a1*x0*exp(a1*(x0*x1 - 1.0_wp))/x1
            qn0_a(1) = qn0_a(1) + (-d_a(1)*x2)
            qn0_a(2) = qn0_a(2) + (-d_a(2)*x2)
            qn0_a(3) = qn0_a(3) + (-d_a(3)*x2)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = 1.0_wp/R_a
            x6 = exp(a1*(x4*x5 - 1.0_wp))
            x7 = a1*x5*x6
            x8 = x7/x4
            x9 = 1.0_wp/(x3*sqrt(x3))
            x10 = (a1*a1)*x6/((R_a*R_a)*x3)
            x11 = x7*x9
            x12 = d_a(1)*d_a(2)
            x13 = -x10*x12 + x11*x12
            x14 = d_a(1)*d_a(3)
            x15 = -x10*x14 + x11*x14
            x16 = d_a(2)*d_a(3)
            x17 = -x10*x16 + x11*x16
            qn0_a(1) = qn0_a(1) + (-d_a(1)*x8)
            qn0_a(2) = qn0_a(2) + (-d_a(2)*x8)
            qn0_a(3) = qn0_a(3) + (-d_a(3)*x8)
            qn1_r_a(1, 1) = qn1_r_a(1, 1) + (a1*x0*x5*x6*x9 - x0*x10 - x8)
            qn1_r_a(1, 2) = qn1_r_a(1, 2) + (x13)
            qn1_r_a(1, 3) = qn1_r_a(1, 3) + (x15)
            qn1_r_a(2, 1) = qn1_r_a(2, 1) + (x13)
            qn1_r_a(2, 2) = qn1_r_a(2, 2) + (a1*x1*x5*x6*x9 - x1*x10 - x8)
            qn1_r_a(2, 3) = qn1_r_a(2, 3) + (x17)
            qn1_r_a(3, 1) = qn1_r_a(3, 1) + (x15)
            qn1_r_a(3, 2) = qn1_r_a(3, 2) + (x17)
            qn1_r_a(3, 3) = qn1_r_a(3, 3) + (a1*x2*x5*x6*x9 - x10*x2 - x8)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45
            real(wp) :: t_qn2_rr_a_010, t_qn2_rr_a_011, t_qn2_rr_a_012, t_qn2_rr_a_020
            real(wp) :: t_qn2_rr_a_021, t_qn2_rr_a_022, t_qn2_rr_a_120, t_qn2_rr_a_121
            real(wp) :: t_qn2_rr_a_122

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = 1.0_wp/R_a
            x6 = exp(a1*(x4*x5 - 1.0_wp))
            x7 = a1*x5*x6
            x8 = x7/x4
            x9 = 1.0_wp/(x3*sqrt(x3))
            x10 = x0*x6
            x11 = (a1*a1)
            x12 = 1.0_wp/(R_a*R_a)
            x13 = x11*x12/x3
            x14 = x7*x9
            x15 = d_a(2)*x14
            x16 = x13*x6
            x17 = d_a(2)*x16
            x18 = d_a(1)*x15 - d_a(1)*x17
            x19 = d_a(3)*x16
            x20 = d_a(1)*d_a(3)*x14 - d_a(1)*x19
            x21 = d_a(3)*x15 - d_a(3)*x17
            x22 = d_a(1)*x16
            x23 = (d_a(1)*d_a(1)*d_a(1))
            x24 = 3.0_wp*x7/(x3*x3*sqrt(x3))
            x25 = (a1*a1*a1)*x9/(R_a*R_a*R_a)
            x26 = 1.0_wp/(x3*x3)
            x27 = x10*x25
            x28 = x0*x24
            x29 = -a1*d_a(2)*x5*x6*x9 + x17
            x30 = 3.0_wp*d_a(2)*x0*x11*x12*x26*x6 - d_a(2)*x27 - d_a(2)*x28 - x29
            x31 = -a1*d_a(3)*x5*x6*x9 + x19
            x32 = 3.0_wp*d_a(3)*x0*x11*x12*x26*x6 - d_a(3)*x27 - d_a(3)*x28 - x31
            x33 = x25*x6
            x34 = d_a(1)*x33
            x35 = -a1*d_a(1)*x5*x6*x9 + x22
            x36 = 3.0_wp*d_a(1)*x1*x11*x12*x26*x6 - d_a(1)*x1*x24 - x1*x34 - x35
            x37 = d_a(2)*d_a(3)
            x38 = 3.0_wp*d_a(1)*d_a(2)*d_a(3)*x11*x12*x26*x6 - d_a(1)*x24*x37 - x34*x37
            x39 = 3.0_wp*d_a(1)*x11*x12*x2*x26*x6 - d_a(1)*x2*x24 - x2*x34 - x35
            x40 = (d_a(2)*d_a(2)*d_a(2))
            x41 = d_a(3)*x1
            x42 = 3.0_wp*d_a(3)*x1*x11*x12*x26*x6 - x24*x41 - x31 - x33*x41
            x43 = d_a(2)*x2
            x44 = 3.0_wp*d_a(2)*x11*x12*x2*x26*x6 - x24*x43 - x29 - x33*x43
            x45 = (d_a(3)*d_a(3)*d_a(3))
            qn0_a(1) = qn0_a(1) + (-d_a(1)*x8)
            qn0_a(2) = qn0_a(2) + (-d_a(2)*x8)
            qn0_a(3) = qn0_a(3) + (-d_a(3)*x8)
            qn1_r_a(1, 1) = qn1_r_a(1, 1) + (a1*x0*x5*x6*x9 - x10*x13 - x8)
            qn1_r_a(1, 2) = qn1_r_a(1, 2) + (x18)
            qn1_r_a(1, 3) = qn1_r_a(1, 3) + (x20)
            qn1_r_a(2, 1) = qn1_r_a(2, 1) + (x18)
            qn1_r_a(2, 2) = qn1_r_a(2, 2) + (a1*x1*x5*x6*x9 - x1*x16 - x8)
            qn1_r_a(2, 3) = qn1_r_a(2, 3) + (x21)
            qn1_r_a(3, 1) = qn1_r_a(3, 1) + (x20)
            qn1_r_a(3, 2) = qn1_r_a(3, 2) + (x21)
            qn1_r_a(3, 3) = qn1_r_a(3, 3) + (a1*x2*x5*x6*x9 - x16*x2 - x8)
            qn2_rr_a(1, 1, 1) = &
               qn2_rr_a(1, 1, 1) + (3.0_wp*a1*d_a(1)*x5*x6*x9 + 3.0_wp*x11*x12*x23*x26*x6 - &
               3.0_wp*x22 - x23*x24 - x23*x25*x6)
            qn2_rr_a(1, 1, 2) = qn2_rr_a(1, 1, 2) + (x30)
            qn2_rr_a(1, 1, 3) = qn2_rr_a(1, 1, 3) + (x32)
            t_qn2_rr_a_010 = x30
