            x64 = d_a(1)*d_a(3)
            x65 = d_b(1)*d_b(3)
            x66 = x54*x64 + x56*x65
            x67 = -d_a(1)*x62 - x49*x63 + x66
            x68 = -d_b(1)*x62 + d_b(3)*x60 + x33*x64 + x54*x63 - x59*x64
            x69 = d_b(1)*x45
            x70 = d_b(2)*x49
            x71 = -d_a(1)*x70 - d_a(2)*x69 + x57
