            x73 = x14*x56 - x3*x45 - x3*x49 + x54*x9
            x74 = d_a(2)*d_a(3)
            x75 = d_b(2)*d_b(3)
            x76 = x54*x74 + x56*x75
            x77 = -d_a(2)*x62 - d_a(3)*x70 + x76
            x78 = d_a(2)*d_b(3)
            x79 = d_a(3)*d_b(2)
            x80 = -d_b(3)*x51 + x33*x74 + x54*x78 + x54*x79 - x59*x74
            x81 = d_a(1)*d_b(3)
            x82 = -d_a(3)*x69 - x49*x81 + x66
            x83 = -d_a(3)*x51 - x49*x78 + x76
            x84 = x10*x54 + x15*x56 - x4*x45 - x4*x49
            x85 = a2*x27/(x16*sqrt(x16))
            x86 = x35/x16
            x87 = x29*x47
            x88 = -x28 + x43
            x89 = x29*x86
            x90 = d_a(1)*d_b(2)*x56 - x45*x53 + x52*x56 + x55*x85 - x55*x89
            x91 = -x45*x64 + x56*x63 + x56*x81 + x65*x85 - x65*x89
            x92 = x38*x87
            x93 = -x45*x74 + x56*x78 + x56*x79 + x75*x85 - x75*x89
            qn0_a(1) = qn0_a(1) + (4.0_wp*c_par*d_b(1)*x0*x1*x18*x7 - d_a(1)*x24)
            qn0_a(2) = qn0_a(2) + (4.0_wp*c_par*d_b(2)*x0*x1*x18*x7 - d_a(2)*x24)
            qn0_a(3) = qn0_a(3) + (4.0_wp*c_par*d_b(3)*x0*x1*x18*x7 - d_a(3)*x24)
