            qq2_rr_aa(2, 2, 1, 2) = qq2_rr_aa(2, 2, 1, 2) + t_qq2_rr_aa_1101
            qq2_rr_aa(2, 2, 2, 1) = qq2_rr_aa(2, 2, 2, 1) + t_qq2_rr_aa_1101
            t_qq2_rr_aa_1102 = x105
            qq2_rr_aa(2, 2, 1, 3) = qq2_rr_aa(2, 2, 1, 3) + t_qq2_rr_aa_1102
            qq2_rr_aa(2, 2, 3, 1) = qq2_rr_aa(2, 2, 3, 1) + t_qq2_rr_aa_1102
            qq2_rr_aa(2, 2, 2, 2) = &
               qq2_rr_aa(2, 2, 2, 2) + (x110*x85 - x110*x89 + x111*x23 - x111*x28 - x112*x67 + &
               x112*x69 + 6.0_wp*x41 + x70)
            t_qq2_rr_aa_1112 = x116
            qq2_rr_aa(2, 2, 2, 3) = qq2_rr_aa(2, 2, 2, 3) + t_qq2_rr_aa_1112
            qq2_rr_aa(2, 2, 3, 2) = qq2_rr_aa(2, 2, 3, 2) + t_qq2_rr_aa_1112
            qq2_rr_aa(2, 2, 3, 3) = qq2_rr_aa(2, 2, 3, 3) + (x118)
            t_qq2_rr_aa_1200 = x97
            qq2_rr_aa(2, 3, 1, 1) = qq2_rr_aa(2, 3, 1, 1) + t_qq2_rr_aa_1200
            qq2_rr_aa(3, 2, 1, 1) = qq2_rr_aa(3, 2, 1, 1) + t_qq2_rr_aa_1200
            t_qq2_rr_aa_1201 = x105
            qq2_rr_aa(2, 3, 1, 2) = qq2_rr_aa(2, 3, 1, 2) + t_qq2_rr_aa_1201
            qq2_rr_aa(2, 3, 2, 1) = qq2_rr_aa(2, 3, 2, 1) + t_qq2_rr_aa_1201
            qq2_rr_aa(3, 2, 1, 2) = qq2_rr_aa(3, 2, 1, 2) + t_qq2_rr_aa_1201
            qq2_rr_aa(3, 2, 2, 1) = qq2_rr_aa(3, 2, 2, 1) + t_qq2_rr_aa_1201
            t_qq2_rr_aa_1202 = x107
            qq2_rr_aa(2, 3, 1, 3) = qq2_rr_aa(2, 3, 1, 3) + t_qq2_rr_aa_1202
            qq2_rr_aa(2, 3, 3, 1) = qq2_rr_aa(2, 3, 3, 1) + t_qq2_rr_aa_1202
            qq2_rr_aa(3, 2, 1, 3) = qq2_rr_aa(3, 2, 1, 3) + t_qq2_rr_aa_1202
            qq2_rr_aa(3, 2, 3, 1) = qq2_rr_aa(3, 2, 3, 1) + t_qq2_rr_aa_1202
            t_qq2_rr_aa_1211 = x116
            qq2_rr_aa(2, 3, 2, 2) = qq2_rr_aa(2, 3, 2, 2) + t_qq2_rr_aa_1211
            qq2_rr_aa(3, 2, 2, 2) = qq2_rr_aa(3, 2, 2, 2) + t_qq2_rr_aa_1211
            t_qq2_rr_aa_1212 = x118
            qq2_rr_aa(2, 3, 2, 3) = qq2_rr_aa(2, 3, 2, 3) + t_qq2_rr_aa_1212
            qq2_rr_aa(2, 3, 3, 2) = qq2_rr_aa(2, 3, 3, 2) + t_qq2_rr_aa_1212
            qq2_rr_aa(3, 2, 2, 3) = qq2_rr_aa(3, 2, 2, 3) + t_qq2_rr_aa_1212
            qq2_rr_aa(3, 2, 3, 2) = qq2_rr_aa(3, 2, 3, 2) + t_qq2_rr_aa_1212
            t_qq2_rr_aa_1222 = x120
            qq2_rr_aa(2, 3, 3, 3) = qq2_rr_aa(2, 3, 3, 3) + t_qq2_rr_aa_1222
            qq2_rr_aa(3, 2, 3, 3) = qq2_rr_aa(3, 2, 3, 3) + t_qq2_rr_aa_1222
            qq2_rr_aa(3, 3, 1, 1) = qq2_rr_aa(3, 3, 1, 1) + (x100)
            t_qq2_rr_aa_2201 = x107
            qq2_rr_aa(3, 3, 1, 2) = qq2_rr_aa(3, 3, 1, 2) + t_qq2_rr_aa_2201
            qq2_rr_aa(3, 3, 2, 1) = qq2_rr_aa(3, 3, 2, 1) + t_qq2_rr_aa_2201
            t_qq2_rr_aa_2202 = x109
            qq2_rr_aa(3, 3, 1, 3) = qq2_rr_aa(3, 3, 1, 3) + t_qq2_rr_aa_2202
            qq2_rr_aa(3, 3, 3, 1) = qq2_rr_aa(3, 3, 3, 1) + t_qq2_rr_aa_2202
            qq2_rr_aa(3, 3, 2, 2) = qq2_rr_aa(3, 3, 2, 2) + (x118)
            t_qq2_rr_aa_2212 = x120
            qq2_rr_aa(3, 3, 2, 3) = qq2_rr_aa(3, 3, 2, 3) + t_qq2_rr_aa_2212
            qq2_rr_aa(3, 3, 3, 2) = qq2_rr_aa(3, 3, 3, 2) + t_qq2_rr_aa_2212
            qq2_rr_aa(3, 3, 3, 3) = &
               qq2_rr_aa(3, 3, 3, 3) + (x121*x85 - x121*x89 + x122*x23 - x122*x28 - x123*x67 + &
               x123*x69 + 6.0_wp*x52 + x70)
         end block
      end select

   end subroutine cfc_atomic_hessian_eval

   !> Accumulate the uncontracted two-nucleus derivative of the spatial ones.
   !>
   !> Given no direction vector, this returns, for each ordered pair of centers
   !> (A, B) this pair can supply,
   !>
   !>    qq{k}_AB(i1..ik, beta, gamma) = d2/(dr_A,beta dr_B,gamma)
   !>                                      d^k K / dr_i1..dr_ik
   !>
   !> i.e. two nuclear indices, both kept.  This is the uncontracted sibling of
   !> `*_hvp_eval`, and the object `cfc_hessian_eval` lifts into `f2_rArB`,
   !> `f3_r_rArB` and `f4_rr_rArB`.  Nuclear signs are already applied (the two
   !> flips cancel).
   !>
   !> Which block a caller wants follows from the atom pair it is filling.  For
   !> an off-diagonal (A, B) only the pair term containing *both* survives two
   !> different nuclear derivatives, so a single call with A in slot a and B in
   !> slot b supplies everything through the `_ab` block.  For a diagonal
   !> (A, A) the contributions are atom A's own term plus the `_aa`/`_bb` block
   !> of every pair containing A, which is one sweep over the partners.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    d_b        Displacement r - r_b
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    R_b        Radius of atom b
   !> @param[in]    a2         Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
   !> @param[in]    c_par      Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..2); a larger value
   !>                          is treated as 2
   !> @param[inout] qq0_aa     d2/(dr_a dr_a) of the order-0 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms a and a
   !> @param[inout] qq0_ab     d2/(dr_a dr_b) of the order-0 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms a and b
   !> @param[inout] qq0_bb     d2/(dr_b dr_b) of the order-0 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms b and b
   !> @param[inout] qq1_r_aa   d2/(dr_a dr_a) of the order-1 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms a and a
   !> @param[inout] qq1_r_ab   d2/(dr_a dr_b) of the order-1 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms a and b
   !> @param[inout] qq1_r_bb   d2/(dr_b dr_b) of the order-1 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms b and b
   !> @param[inout] qq2_rr_aa  d2/(dr_a dr_a) of the order-2 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms a and a
   !> @param[inout] qq2_rr_ab  d2/(dr_a dr_b) of the order-2 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms a and b
   !> @param[inout] qq2_rr_bb  d2/(dr_b dr_b) of the order-2 spatial derivative; the two trailing
   !>                          indices are the nuclear components of atoms b and b
   pure subroutine cfc_pair_hessian_eval(d_a, d_b, R_a, R_b, a2, c_par, max_deriv, qq0_aa, &
                                         qq0_ab, qq0_bb, qq1_r_aa, qq1_r_ab, qq1_r_bb, qq2_rr_aa, &
                                         qq2_rr_ab, qq2_rr_bb)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Highest spatial-derivative order to accumulate (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dr_a dr_a) of the order-0 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and a
      real(wp), intent(inout) :: qq0_aa(3, 3)
      !> d2/(dr_a dr_b) of the order-0 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and b
      real(wp), intent(inout) :: qq0_ab(3, 3)
      !> d2/(dr_b dr_b) of the order-0 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms b and b
      real(wp), intent(inout) :: qq0_bb(3, 3)
      !> d2/(dr_a dr_a) of the order-1 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and a
      real(wp), intent(inout) :: qq1_r_aa(3, 3, 3)
      !> d2/(dr_a dr_b) of the order-1 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and b
      real(wp), intent(inout) :: qq1_r_ab(3, 3, 3)
      !> d2/(dr_b dr_b) of the order-1 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms b and b
      real(wp), intent(inout) :: qq1_r_bb(3, 3, 3)
      !> d2/(dr_a dr_a) of the order-2 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and a
      real(wp), intent(inout) :: qq2_rr_aa(3, 3, 3, 3)
      !> d2/(dr_a dr_b) of the order-2 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and b
      real(wp), intent(inout) :: qq2_rr_ab(3, 3, 3, 3)
      !> d2/(dr_b dr_b) of the order-2 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms b and b
      real(wp), intent(inout) :: qq2_rr_bb(3, 3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, t_qq0_aa_01, t_qq0_aa_02, t_qq0_aa_12, t_qq0_bb_01
            real(wp) :: t_qq0_bb_02, t_qq0_bb_12

            x0 = (d_b(1)*d_b(1))
            x1 = 1.0_wp/(R_b*R_b)
            x2 = x0*x1
            x3 = 1.0_wp/(R_a*R_a)
            x4 = d_a(1)*d_b(1)
            x5 = d_a(2)*d_b(2)
            x6 = d_a(3)*d_b(3)
            x7 = 1.0_wp/R_a
            x8 = 1.0_wp/R_b
            x9 = x7*x8
            x10 = -x9*(x4 + x5 + x6) + 1.0_wp
            x11 = (x10*x10)
            x12 = (d_a(1)*d_a(1))
            x13 = (d_a(2)*d_a(2))
            x14 = (d_a(3)*d_a(3))
            x15 = x12 + x13 + x14
            x16 = sqrt(x15)
            x17 = (d_b(2)*d_b(2))
            x18 = (d_b(3)*d_b(3))
            x19 = x0 + x17 + x18
            x20 = sqrt(x19)
            x21 = exp(a2*(x16*x7 + x20*x8 - 2.0_wp))
            x22 = c_par*x21
            x23 = 12.0_wp*x11*x22*x3
            x24 = 1.0_wp/x16
            x25 = (x10*x10*x10*x10)
            x26 = x22*x25
            x27 = a2*x26
            x28 = x27*x7
            x29 = x24*x28
            x30 = x28/(x15*sqrt(x15))
            x31 = x12*x3
            x32 = 1.0_wp/x15
            x33 = (a2*a2)
            x34 = x26*x33
            x35 = x32*x34
            x36 = (x10*x10*x10)*x22
            x37 = 8.0_wp*a2*x36
            x38 = x37*x4
            x39 = x24*x8
            x40 = x3*x39
            x41 = d_a(1)*d_a(2)
            x42 = 4.0_wp*x36
            x43 = a2*x42
            x44 = x39*x43
            x45 = x3*x44
            x46 = d_a(1)*x45
            x47 = d_b(1)*x45
            x48 = d_a(1)*d_a(3)
            x49 = x1*x23
            x50 = x3*x35
            x51 = x37*x40
            x52 = d_a(2)*d_a(3)
            x53 = d_a(2)*d_b(3)
            x54 = d_a(3)*d_b(2)
            x55 = x42*x9
            x56 = 1.0_wp/x20
            x57 = x56*x7
            x58 = x43*x57
            x59 = d_b(1)*x49
            x60 = x24*x34*x56*x9
            x61 = d_a(1)*x60
            x62 = d_b(1)*d_b(2)
            x63 = x1*x58
            x64 = -x41*x45 - x62*x63
            x65 = d_b(1)*d_b(3)
            x66 = -x45*x48 - x63*x65
            x67 = d_b(2)*x49
            x68 = d_b(1)*x60
            x69 = d_b(2)*d_b(3)
            x70 = -x45*x52 - x63*x69
            x71 = d_b(3)*x49
            x72 = x27*x8
            x73 = x56*x72
            x74 = x72/(x19*sqrt(x19))
            x75 = 1.0_wp/x19
            x76 = x34*x75
            x77 = x1*x57
            x78 = d_a(1)*x63
            x79 = d_b(1)*x63
            x80 = x1*x76
            x81 = x37*x77
            qq0_aa(1, 1) = qq0_aa(1, 1) + (-x12*x30 + x2*x23 + x29 + x31*x35 - x38*x40)
            t_qq0_aa_01 = &
               c_par*d_a(1)*d_a(2)*x21*x25*x3*x32*x33 + 12.0_wp*c_par*d_b(1)*d_b(2)*x1*x11*x21*x3 &
               - d_a(2)*x47 - d_b(2)*x46 - x30*x41
            qq0_aa(1, 2) = qq0_aa(1, 2) + t_qq0_aa_01
            qq0_aa(2, 1) = qq0_aa(2, 1) + t_qq0_aa_01
            t_qq0_aa_02 = &
               c_par*d_a(1)*d_a(3)*x21*x25*x3*x32*x33 + 12.0_wp*c_par*d_b(1)*d_b(3)*x1*x11*x21*x3 &
               - d_a(3)*x47 - d_b(3)*x46 - x30*x48
            qq0_aa(1, 3) = qq0_aa(1, 3) + t_qq0_aa_02
            qq0_aa(3, 1) = qq0_aa(3, 1) + t_qq0_aa_02
            qq0_aa(2, 2) = qq0_aa(2, 2) + (-x13*x30 + x13*x50 + x17*x49 + x29 - x5*x51)
            t_qq0_aa_12 = &
               c_par*d_a(2)*d_a(3)*x21*x25*x3*x32*x33 + 12.0_wp*c_par*d_b(2)*d_b(3)*x1*x11*x21*x3 &
               - x30*x52 - x45*x53 - x45*x54
            qq0_aa(2, 3) = qq0_aa(2, 3) + t_qq0_aa_12
            qq0_aa(3, 2) = qq0_aa(3, 2) + t_qq0_aa_12
            qq0_aa(3, 3) = qq0_aa(3, 3) + (-x14*x30 + x14*x50 + x18*x49 + x29 - x51*x6)
            qq0_ab(1, 1) = &
               qq0_ab(1, 1) + (12.0_wp*c_par*d_a(1)*d_b(1)*x1*x11*x21*x3 + &
               c_par*d_a(1)*d_b(1)*x21*x24*x25*x33*x56*x7*x8 - x2*x58 - x31*x44 - x55)
            qq0_ab(1, 2) = qq0_ab(1, 2) + (d_a(2)*x59 + d_b(2)*x61 + x64)
            qq0_ab(1, 3) = qq0_ab(1, 3) + (d_a(3)*x59 + d_b(3)*x61 + x66)
            qq0_ab(2, 1) = qq0_ab(2, 1) + (d_a(1)*x67 + d_a(2)*x68 + x64)
            qq0_ab(2, 2) = &
               qq0_ab(2, 2) + (12.0_wp*c_par*d_a(2)*d_b(2)*x1*x11*x21*x3 + &
               c_par*d_a(2)*d_b(2)*x21*x24*x25*x33*x56*x7*x8 - x13*x45 - x17*x63 - x55)
            qq0_ab(2, 3) = qq0_ab(2, 3) + (d_a(3)*x67 + x53*x60 + x70)
            qq0_ab(3, 1) = qq0_ab(3, 1) + (d_a(1)*x71 + d_a(3)*x68 + x66)
            qq0_ab(3, 2) = qq0_ab(3, 2) + (d_a(2)*x71 + x54*x60 + x70)
            qq0_ab(3, 3) = &
               qq0_ab(3, 3) + (12.0_wp*c_par*d_a(3)*d_b(3)*x1*x11*x21*x3 + &
               c_par*d_a(3)*d_b(3)*x21*x24*x25*x33*x56*x7*x8 - x14*x45 - x18*x63 - x55)
            qq0_bb(1, 1) = qq0_bb(1, 1) + (-x0*x74 + x12*x49 + x2*x76 - x38*x77 + x73)
            t_qq0_bb_01 = &
               12.0_wp*c_par*d_a(1)*d_a(2)*x1*x11*x21*x3 + c_par*d_b(1)*d_b(2)*x1*x21*x25*x33*x75 &
               - d_a(2)*x79 - d_b(2)*x78 - x62*x74
            qq0_bb(1, 2) = qq0_bb(1, 2) + t_qq0_bb_01
            qq0_bb(2, 1) = qq0_bb(2, 1) + t_qq0_bb_01
            t_qq0_bb_02 = &
               12.0_wp*c_par*d_a(1)*d_a(3)*x1*x11*x21*x3 + c_par*d_b(1)*d_b(3)*x1*x21*x25*x33*x75 &
               - d_a(3)*x79 - d_b(3)*x78 - x65*x74
            qq0_bb(1, 3) = qq0_bb(1, 3) + t_qq0_bb_02
            qq0_bb(3, 1) = qq0_bb(3, 1) + t_qq0_bb_02
            qq0_bb(2, 2) = qq0_bb(2, 2) + (x13*x49 - x17*x74 + x17*x80 - x5*x81 + x73)
            t_qq0_bb_12 = &
               12.0_wp*c_par*d_a(2)*d_a(3)*x1*x11*x21*x3 + c_par*d_b(2)*d_b(3)*x1*x21*x25*x33*x75 &
               - x53*x63 - x54*x63 - x69*x74
            qq0_bb(2, 3) = qq0_bb(2, 3) + t_qq0_bb_12
            qq0_bb(3, 2) = qq0_bb(3, 2) + t_qq0_bb_12
            qq0_bb(3, 3) = qq0_bb(3, 3) + (x14*x49 - x18*x74 + x18*x80 - x6*x81 + x73)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93, x94, x95, x96, x97, x98, x99, x100, x101, x102, x103, x104, x105
            real(wp) :: x106, x107, x108, x109, x110, x111, x112, x113, x114, x115, x116, x117, x118
            real(wp) :: x119, x120, x121, x122, x123, x124, x125, x126, x127, x128, x129, x130, x131
            real(wp) :: x132, x133, x134, x135, x136, x137, x138, x139, x140, x141, x142, x143, x144
