   !> Accumulate the radius derivative of the spatial derivatives.
   !>
   !> Given no direction vector, this returns, for each center A of this atom,
   !>
   !>    rd{k}_A(i1..ik) = d/dR_A  d^k K / dr_i1..dr_ik
   !>
   !> where ``R_A`` is atom A's *cavity radius*, a parameter of the level set
   !> rather than a coordinate.  Three consequences, all visible in the
   !> signature: no direction vector, no sign flip (the displacement is
   !> ``r - r_a``, so positions flip and radii do not), and no trailing index --
   !> a radius is a scalar, so the result has exactly the rank of the spatial
   !> tensor it came from.  Contrast `*_nuclear_eval`, whose output grows one
   !> Cartesian index.
   !>
   !> Summed over an atom's own term and every pair it belongs to, this is the
   !> per-atom family `cfc_radius_eval` lifts into `f1_rad` .. `f4_rrr_rad`.
   !> A caller wanting radius derivatives wants the spatial ones too, and runs
   !> `*_spatial_eval` alongside this.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    a1         Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..3); a larger value
   !>                          is treated as 3
   !> @param[inout] rd0_a      d/dR_a of the order-0 spatial derivative; R_a is atom a's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd1_r_a    d/dR_a of the order-1 spatial derivative; R_a is atom a's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd2_rr_a   d/dR_a of the order-2 spatial derivative; R_a is atom a's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd3_rrr_a  d/dR_a of the order-3 spatial derivative; R_a is atom a's radius, so
   !>                          there is no trailing nuclear index
   pure subroutine cfc_atomic_radius_eval(d_a, R_a, a1, max_deriv, rd0_a, rd1_r_a, rd2_rr_a, &
                                          rd3_rrr_a)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dR_a of the order-0 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd0_a
      !> d/dR_a of the order-1 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd1_r_a(3)
      !> d/dR_a of the order-2 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd2_rr_a(3, 3)
      !> d/dR_a of the order-3 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd3_rrr_a(3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            rd0_a = rd0_a + (-a1*x0*exp(a1*(-1.0_wp + x0/R_a))/(R_a*R_a))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x1 = exp(a1*(-1.0_wp + x0/R_a))
            x2 = a1*x1/(R_a*R_a)
            x3 = (a1*a1)*x1/(R_a*R_a*R_a)
            x4 = x2/x0
            rd0_a = rd0_a + (-x0*x2)
            rd1_r_a(1) = rd1_r_a(1) + (-d_a(1)*x3 - d_a(1)*x4)
            rd1_r_a(2) = rd1_r_a(2) + (-d_a(2)*x3 - d_a(2)*x4)
            rd1_r_a(3) = rd1_r_a(3) + (-d_a(3)*x3 - d_a(3)*x4)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, t_rd2_rr_a_01, t_rd2_rr_a_02, t_rd2_rr_a_12

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = exp(a1*(-1.0_wp + x4/R_a))
            x6 = 1.0_wp/(R_a*R_a)
            x7 = a1*x5*x6
            x8 = (a1*a1)*x5/(R_a*R_a*R_a)
            x9 = d_a(1)*x8
            x10 = 1.0_wp/x4
            x11 = x10*x7
            x12 = d_a(2)*x8
            x13 = 1.0_wp/x3
            x14 = x13*x8
            x15 = (a1*a1*a1)*x10*x5/(R_a*R_a*R_a*R_a)
            x16 = 1.0_wp/(x3*sqrt(x3))
            x17 = x11 + x8
            x18 = x13*x9
            rd0_a = rd0_a + (-x4*x7)
            rd1_r_a(1) = rd1_r_a(1) + (-d_a(1)*x11 - x9)
            rd1_r_a(2) = rd1_r_a(2) + (-d_a(2)*x11 - x12)
            rd1_r_a(3) = rd1_r_a(3) + (-d_a(3)*x11 - d_a(3)*x8)
            rd2_rr_a(1, 1) = rd2_rr_a(1, 1) + (a1*x0*x16*x5*x6 - x0*x14 - x0*x15 - x17)
            t_rd2_rr_a_01 = a1*d_a(1)*d_a(2)*x16*x5*x6 - d_a(1)*d_a(2)*x15 - d_a(2)*x18
            rd2_rr_a(1, 2) = rd2_rr_a(1, 2) + t_rd2_rr_a_01
            rd2_rr_a(2, 1) = rd2_rr_a(2, 1) + t_rd2_rr_a_01
            t_rd2_rr_a_02 = a1*d_a(1)*d_a(3)*x16*x5*x6 - d_a(1)*d_a(3)*x15 - d_a(3)*x18
            rd2_rr_a(1, 3) = rd2_rr_a(1, 3) + t_rd2_rr_a_02
            rd2_rr_a(3, 1) = rd2_rr_a(3, 1) + t_rd2_rr_a_02
            rd2_rr_a(2, 2) = rd2_rr_a(2, 2) + (a1*x1*x16*x5*x6 - x1*x14 - x1*x15 - x17)
            t_rd2_rr_a_12 = a1*d_a(2)*d_a(3)*x16*x5*x6 - d_a(2)*d_a(3)*x15 - d_a(3)*x12*x13
            rd2_rr_a(2, 3) = rd2_rr_a(2, 3) + t_rd2_rr_a_12
            rd2_rr_a(3, 2) = rd2_rr_a(3, 2) + t_rd2_rr_a_12
            rd2_rr_a(3, 3) = rd2_rr_a(3, 3) + (a1*x16*x2*x5*x6 - x14*x2 - x15*x2 - x17)
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: t_rd2_rr_a_01, t_rd2_rr_a_02, t_rd2_rr_a_12, t_rd3_rrr_a_001
            real(wp) :: t_rd3_rrr_a_002, t_rd3_rrr_a_011, t_rd3_rrr_a_012, t_rd3_rrr_a_022
            real(wp) :: t_rd3_rrr_a_112, t_rd3_rrr_a_122

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = exp(a1*(-1.0_wp + x4/R_a))
            x6 = 1.0_wp/(R_a*R_a)
            x7 = a1*x5*x6
            x8 = 1.0_wp/(R_a*R_a*R_a)
            x9 = (a1*a1)
            x10 = x5*x8*x9
            x11 = d_a(1)*x10
            x12 = 1.0_wp/x4
            x13 = x12*x7
            x14 = d_a(2)*x10
            x15 = d_a(3)*x10
            x16 = 1.0_wp/x3
            x17 = x10*x16
            x18 = x0*x5
            x19 = (a1*a1*a1)*x12/(R_a*R_a*R_a*R_a)
            x20 = 1.0_wp/(x3*sqrt(x3))
            x21 = x10 + x13
            x22 = x19*x5
            x23 = d_a(2)*x22
            x24 = x11*x16
            x25 = d_a(3)*x22
            x26 = x14*x16
            x27 = d_a(1)*x22
            x28 = (d_a(1)*d_a(1)*d_a(1))
            x29 = x7/(x3*x3*sqrt(x3))
            x30 = (a1*a1*a1*a1)*x16/(R_a*R_a*R_a*R_a*R_a)
            x31 = x30*x5
            x32 = 1.0_wp/(x3*x3)
            x33 = x18*x30
            x34 = 3.0_wp*x0*x29
            x35 = -a1*d_a(2)*x20*x5*x6 + x23 + x26
            x36 = x15*x16
            x37 = -a1*d_a(3)*x20*x5*x6 + x25 + x36
            x38 = d_a(1)*x31
            x39 = d_a(1)*x29
            x40 = -a1*d_a(1)*x20*x5*x6 + x24 + x27
            x41 = d_a(2)*d_a(3)
            x42 = (d_a(2)*d_a(2)*d_a(2))
            x43 = d_a(3)*x1
            x44 = 3.0_wp*x29
            x45 = d_a(2)*x2
            x46 = (d_a(3)*d_a(3)*d_a(3))
            rd0_a = rd0_a + (-x4*x7)
            rd1_r_a(1) = rd1_r_a(1) + (-d_a(1)*x13 - x11)
            rd1_r_a(2) = rd1_r_a(2) + (-d_a(2)*x13 - x14)
            rd1_r_a(3) = rd1_r_a(3) + (-d_a(3)*x13 - x15)
            rd2_rr_a(1, 1) = rd2_rr_a(1, 1) + (a1*x0*x20*x5*x6 - x0*x17 - x18*x19 - x21)
            t_rd2_rr_a_01 = a1*d_a(1)*d_a(2)*x20*x5*x6 - d_a(1)*x23 - d_a(2)*x24
            rd2_rr_a(1, 2) = rd2_rr_a(1, 2) + t_rd2_rr_a_01
            rd2_rr_a(2, 1) = rd2_rr_a(2, 1) + t_rd2_rr_a_01
            t_rd2_rr_a_02 = a1*d_a(1)*d_a(3)*x20*x5*x6 - d_a(1)*x25 - d_a(3)*x24
            rd2_rr_a(1, 3) = rd2_rr_a(1, 3) + t_rd2_rr_a_02
            rd2_rr_a(3, 1) = rd2_rr_a(3, 1) + t_rd2_rr_a_02
            rd2_rr_a(2, 2) = rd2_rr_a(2, 2) + (a1*x1*x20*x5*x6 - x1*x17 - x1*x22 - x21)
            t_rd2_rr_a_12 = a1*d_a(2)*d_a(3)*x20*x5*x6 - d_a(3)*x23 - d_a(3)*x26
            rd2_rr_a(2, 3) = rd2_rr_a(2, 3) + t_rd2_rr_a_12
            rd2_rr_a(3, 2) = rd2_rr_a(3, 2) + t_rd2_rr_a_12
            rd2_rr_a(3, 3) = rd2_rr_a(3, 3) + (a1*x2*x20*x5*x6 - x17*x2 - x2*x22 - x21)
            rd3_rrr_a(1, 1, 1) = &
               rd3_rrr_a(1, 1, 1) + (3.0_wp*a1*d_a(1)*x20*x5*x6 - 3.0_wp*x24 - 3.0_wp*x27 - &
               3.0_wp*x28*x29 - x28*x31 + 3.0_wp*x28*x32*x5*x8*x9)
            t_rd3_rrr_a_001 = 3.0_wp*d_a(2)*x0*x32*x5*x8*x9 - d_a(2)*x33 - d_a(2)*x34 - x35
            rd3_rrr_a(1, 1, 2) = rd3_rrr_a(1, 1, 2) + t_rd3_rrr_a_001
            rd3_rrr_a(1, 2, 1) = rd3_rrr_a(1, 2, 1) + t_rd3_rrr_a_001
            rd3_rrr_a(2, 1, 1) = rd3_rrr_a(2, 1, 1) + t_rd3_rrr_a_001
            t_rd3_rrr_a_002 = 3.0_wp*d_a(3)*x0*x32*x5*x8*x9 - d_a(3)*x33 - d_a(3)*x34 - x37
            rd3_rrr_a(1, 1, 3) = rd3_rrr_a(1, 1, 3) + t_rd3_rrr_a_002
            rd3_rrr_a(1, 3, 1) = rd3_rrr_a(1, 3, 1) + t_rd3_rrr_a_002
            rd3_rrr_a(3, 1, 1) = rd3_rrr_a(3, 1, 1) + t_rd3_rrr_a_002
            t_rd3_rrr_a_011 = 3.0_wp*d_a(1)*x1*x32*x5*x8*x9 - x1*x38 - 3.0_wp*x1*x39 - x40
            rd3_rrr_a(1, 2, 2) = rd3_rrr_a(1, 2, 2) + t_rd3_rrr_a_011
            rd3_rrr_a(2, 1, 2) = rd3_rrr_a(2, 1, 2) + t_rd3_rrr_a_011
            rd3_rrr_a(2, 2, 1) = rd3_rrr_a(2, 2, 1) + t_rd3_rrr_a_011
            t_rd3_rrr_a_012 = 3.0_wp*d_a(1)*d_a(2)*d_a(3)*x32*x5*x8*x9 - x38*x41 - 3.0_wp*x39*x41
            rd3_rrr_a(1, 2, 3) = rd3_rrr_a(1, 2, 3) + t_rd3_rrr_a_012
            rd3_rrr_a(1, 3, 2) = rd3_rrr_a(1, 3, 2) + t_rd3_rrr_a_012
            rd3_rrr_a(2, 1, 3) = rd3_rrr_a(2, 1, 3) + t_rd3_rrr_a_012
            rd3_rrr_a(2, 3, 1) = rd3_rrr_a(2, 3, 1) + t_rd3_rrr_a_012
            rd3_rrr_a(3, 1, 2) = rd3_rrr_a(3, 1, 2) + t_rd3_rrr_a_012
            rd3_rrr_a(3, 2, 1) = rd3_rrr_a(3, 2, 1) + t_rd3_rrr_a_012
            t_rd3_rrr_a_022 = 3.0_wp*d_a(1)*x2*x32*x5*x8*x9 - x2*x38 - 3.0_wp*x2*x39 - x40
            rd3_rrr_a(1, 3, 3) = rd3_rrr_a(1, 3, 3) + t_rd3_rrr_a_022
            rd3_rrr_a(3, 1, 3) = rd3_rrr_a(3, 1, 3) + t_rd3_rrr_a_022
            rd3_rrr_a(3, 3, 1) = rd3_rrr_a(3, 3, 1) + t_rd3_rrr_a_022
            rd3_rrr_a(2, 2, 2) = &
               rd3_rrr_a(2, 2, 2) + (3.0_wp*a1*d_a(2)*x20*x5*x6 - 3.0_wp*x23 - 3.0_wp*x26 - &
               3.0_wp*x29*x42 - x31*x42 + 3.0_wp*x32*x42*x5*x8*x9)
            t_rd3_rrr_a_112 = 3.0_wp*d_a(3)*x1*x32*x5*x8*x9 - x31*x43 - x37 - x43*x44
            rd3_rrr_a(2, 2, 3) = rd3_rrr_a(2, 2, 3) + t_rd3_rrr_a_112
            rd3_rrr_a(2, 3, 2) = rd3_rrr_a(2, 3, 2) + t_rd3_rrr_a_112
            rd3_rrr_a(3, 2, 2) = rd3_rrr_a(3, 2, 2) + t_rd3_rrr_a_112
            t_rd3_rrr_a_122 = 3.0_wp*d_a(2)*x2*x32*x5*x8*x9 - x31*x45 - x35 - x44*x45
            rd3_rrr_a(2, 3, 3) = rd3_rrr_a(2, 3, 3) + t_rd3_rrr_a_122
            rd3_rrr_a(3, 2, 3) = rd3_rrr_a(3, 2, 3) + t_rd3_rrr_a_122
            rd3_rrr_a(3, 3, 2) = rd3_rrr_a(3, 3, 2) + t_rd3_rrr_a_122
            rd3_rrr_a(3, 3, 3) = &
               rd3_rrr_a(3, 3, 3) + (3.0_wp*a1*d_a(3)*x20*x5*x6 - 3.0_wp*x25 - 3.0_wp*x29*x46 - &
               x31*x46 + 3.0_wp*x32*x46*x5*x8*x9 - 3.0_wp*x36)
         end block
      end select

   end subroutine cfc_atomic_radius_eval

   !> Accumulate the radius derivative of the spatial derivatives.
   !>
   !> Given no direction vector, this returns, for each center A of this pair,
   !>
   !>    rd{k}_A(i1..ik) = d/dR_A  d^k K / dr_i1..dr_ik
   !>
   !> where ``R_A`` is atom A's *cavity radius*, a parameter of the level set
   !> rather than a coordinate.  Three consequences, all visible in the
   !> signature: no direction vector, no sign flip (the displacement is
   !> ``r - r_a``, so positions flip and radii do not), and no trailing index --
   !> a radius is a scalar, so the result has exactly the rank of the spatial
   !> tensor it came from.  Contrast `*_nuclear_eval`, whose output grows one
   !> Cartesian index.
   !>
   !> Summed over an atom's own term and every pair it belongs to, this is the
   !> per-atom family `cfc_radius_eval` lifts into `f1_rad` .. `f4_rrr_rad`.
   !> A caller wanting radius derivatives wants the spatial ones too, and runs
   !> `*_spatial_eval` alongside this.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    d_b        Displacement r - r_b
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    R_b        Radius of atom b
   !> @param[in]    a2         Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
   !> @param[in]    c_par      Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..3); a larger value
   !>                          is treated as 3
   !> @param[inout] rd0_a      d/dR_a of the order-0 spatial derivative; R_a is atom a's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd0_b      d/dR_b of the order-0 spatial derivative; R_b is atom b's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd1_r_a    d/dR_a of the order-1 spatial derivative; R_a is atom a's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd1_r_b    d/dR_b of the order-1 spatial derivative; R_b is atom b's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd2_rr_a   d/dR_a of the order-2 spatial derivative; R_a is atom a's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd2_rr_b   d/dR_b of the order-2 spatial derivative; R_b is atom b's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd3_rrr_a  d/dR_a of the order-3 spatial derivative; R_a is atom a's radius, so
   !>                          there is no trailing nuclear index
   !> @param[inout] rd3_rrr_b  d/dR_b of the order-3 spatial derivative; R_b is atom b's radius, so
   !>                          there is no trailing nuclear index
   pure subroutine cfc_pair_radius_eval(d_a, d_b, R_a, R_b, a2, c_par, max_deriv, rd0_a, rd0_b, &
                                        rd1_r_a, rd1_r_b, rd2_rr_a, rd2_rr_b, rd3_rrr_a, rd3_rrr_b)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dR_a of the order-0 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd0_a
      !> d/dR_b of the order-0 spatial derivative; R_b is atom b's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd0_b
      !> d/dR_a of the order-1 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd1_r_a(3)
      !> d/dR_b of the order-1 spatial derivative; R_b is atom b's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd1_r_b(3)
      !> d/dR_a of the order-2 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd2_rr_a(3, 3)
      !> d/dR_b of the order-2 spatial derivative; R_b is atom b's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd2_rr_b(3, 3)
      !> d/dR_a of the order-3 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd3_rrr_a(3, 3, 3)
      !> d/dR_b of the order-3 spatial derivative; R_b is atom b's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd3_rrr_b(3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x1 = 1.0_wp/(R_a*R_a)
            x2 = 1.0_wp/R_a
            x3 = 1.0_wp/R_b
            x4 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x5 = exp(a2*(x0*x2 + x3*x4 - 2.0_wp))
            x6 = c_par*x5
            x7 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
            x8 = -x2*x3*x7 + 1.0_wp
            x9 = a2*(x8*x8*x8*x8)
            x10 = (x8*x8*x8)
            x11 = 1.0_wp/(R_b*R_b)
            rd0_a = rd0_a + (4.0_wp*c_par*x1*x10*x3*x5*x7 - x0*x1*x6*x9)
            rd0_b = rd0_b + (4.0_wp*c_par*x10*x11*x2*x5*x7 - x11*x4*x6*x9)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x1 = 1.0_wp/(R_a*R_a)
            x2 = 1.0_wp/R_a
            x3 = 1.0_wp/R_b
            x4 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
            x5 = x3*x4
            x6 = -x2*x5 + 1.0_wp
            x7 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x8 = exp(a2*(x0*x2 + x3*x7 - 2.0_wp))
            x9 = c_par*x8
            x10 = (x6*x6*x6*x6)*x9
            x11 = a2*x10
            x12 = x1*x11
            x13 = (x6*x6*x6)
            x14 = 1.0_wp/(R_b*R_b)
            x15 = x11*x14
            x16 = (a2*a2)*x10
            x17 = 1.0_wp/(R_a*R_a*R_a)
            x18 = d_a(1)*x17
            x19 = x1*x9
            x20 = 4.0_wp*x13
            x21 = x19*x20
            x22 = x21*x3
            x23 = x14*x4
            x24 = 12.0_wp*(x6*x6)
            x25 = x23*x24*x9
            x26 = x17*x25
            x27 = 1.0_wp/x0
            x28 = x12*x27
            x29 = x0*x3
            x30 = x20*x9
            x31 = a2*x30
            x32 = x18*x31
            x33 = d_b(1)*x29
            x34 = x17*x31
            x35 = x27*x5
            x36 = 1.0_wp/x7
            x37 = d_b(1)*x36
            x38 = a2*x21*x23
            x39 = x1*x16*x36
            x40 = x16*x17
            x41 = x29*x34
            x42 = x34*x35
            x43 = x36*x38
            x44 = x29*x39
            x45 = x14*x2
            x46 = x30*x45
            x47 = 1.0_wp/(R_b*R_b*R_b)
            x48 = x16*x47
            x49 = d_a(1)*x47
            x50 = x19*x24*x4
            x51 = x47*x50
            x52 = x15*x36
            x53 = x2*x31
            x54 = x53*x7
            x55 = x47*x54
            x56 = d_a(1)*x27
            x57 = x4*x47*x53
            x58 = x16*x45*x7
            x59 = x27*x38
            x60 = x36*x57
            x61 = x27*x58
            rd0_a = rd0_a + (4.0_wp*c_par*x1*x13*x3*x4*x8 - x0*x12)
            rd0_b = rd0_b + (4.0_wp*c_par*x13*x14*x2*x4*x8 - x15*x7)
