   !> Accumulate the uncontracted two-*radius* derivative of the spatial ones.
   !>
   !> The radius twin of `*_hessian_eval`.  For each pair of centers (A, B) this
   !> atom can supply,
   !>
   !>    rr{k}_AB(i1..ik) = d2/(dRad_A dRad_B)  d^k K / dr_i1..dr_ik
   !>
   !> Two retained radii, both kept, neither adding an index: the results have the
   !> same rank as the spatial tensors they come from, two below the `qq*` family,
   !> and no nuclear sign is involved because a radius is not a coordinate.
   !>
   !> `cfc_radius2_eval` lifts these into `f2_radrad`, `f3_r_radrad` and
   !> `f4_rr_radrad`.  Which block a caller wants follows from the atom pair it is
   !> filling, exactly as for `*_hessian_eval`: `_ab` for an off-diagonal (A, B),
   !> `_aa`/`_bb` swept over the partners for a diagonal (A, A).
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    a1         Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..2); a larger value
   !>                          is treated as 2
   !> @param[inout] rr0_aa     d2/(dR_a dR_a) of the order-0 spatial derivative, where R_a and R_a
   !>                          are the atoms' radii; no trailing index, radii are scalars
   !> @param[inout] rr1_r_aa   d2/(dR_a dR_a) of the order-1 spatial derivative, where R_a and R_a
   !>                          are the atoms' radii; no trailing index, radii are scalars
   !> @param[inout] rr2_rr_aa  d2/(dR_a dR_a) of the order-2 spatial derivative, where R_a and R_a
   !>                          are the atoms' radii; no trailing index, radii are scalars
   pure subroutine cfc_atomic_radius2_eval(d_a, R_a, a1, max_deriv, rr0_aa, rr1_r_aa, rr2_rr_aa)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Highest spatial-derivative order to accumulate (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dR_a dR_a) of the order-0 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr0_aa
      !> d2/(dR_a dR_a) of the order-1 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr1_r_aa(3)
      !> d2/(dR_a dR_a) of the order-2 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr2_rr_aa(3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2

            x0 = 1.0_wp/R_a
            x1 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
            x2 = sqrt(x1)
            rr0_aa = rr0_aa + (a1*(a1*x0*x1 + 2.0_wp*x2)*exp(-a1*(-x0*x2 + 1.0_wp))/(R_a*R_a*R_a))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7

            x0 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
            x1 = sqrt(x0)
            x2 = 1.0_wp/R_a
            x3 = a1*x2
            x4 = x0*x3 + 2.0_wp*x1
            x5 = a1*exp(-a1*(-x1*x2 + 1.0_wp))/(R_a*R_a*R_a)
            x6 = 1.0_wp/x1
            x7 = x5*(x3*x4*x6 + 2.0_wp*x3 + 2.0_wp*x6)
            rr0_aa = rr0_aa + (x4*x5)
            rr1_r_aa(1) = rr1_r_aa(1) + (d_a(1)*x7)
            rr1_r_aa(2) = rr1_r_aa(2) + (d_a(2)*x7)
            rr1_r_aa(3) = rr1_r_aa(3) + (d_a(3)*x7)
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, t_rr2_rr_aa_01, t_rr2_rr_aa_02, t_rr2_rr_aa_12

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = 1.0_wp/R_a
            x6 = a1*x5
            x7 = x3*x6 + 2.0_wp*x4
            x8 = 1.0_wp/(R_a*R_a*R_a)
            x9 = a1*x8*exp(-a1*(-x4*x5 + 1.0_wp))
            x10 = 2.0_wp*x6
            x11 = 1.0_wp/x4
            x12 = 2.0_wp*x11
            x13 = x9*(x10 + x11*x6*x7 + x12)
            x14 = 2.0_wp/(x3*sqrt(x3))
            x15 = (a1*a1*a1)*x8
            x16 = x10/x3
            x17 = (a1*a1)/(R_a*R_a)
            x18 = 5.0_wp*x11*x17
            x19 = x12 + x17*x4 + 4.0_wp*x6
            x20 = -x14 + x15 + x16 + x18
            x21 = d_a(1)*x20*x9
            rr0_aa = rr0_aa + (x7*x9)
            rr1_r_aa(1) = rr1_r_aa(1) + (d_a(1)*x13)
            rr1_r_aa(2) = rr1_r_aa(2) + (d_a(2)*x13)
            rr1_r_aa(3) = rr1_r_aa(3) + (d_a(3)*x13)
            rr2_rr_aa(1, 1) = rr2_rr_aa(1, 1) + (x9*(-x0*x14 + x0*x15 + x0*x16 + x0*x18 + x19))
            t_rr2_rr_aa_01 = d_a(2)*x21
            rr2_rr_aa(1, 2) = rr2_rr_aa(1, 2) + t_rr2_rr_aa_01
            rr2_rr_aa(2, 1) = rr2_rr_aa(2, 1) + t_rr2_rr_aa_01
            t_rr2_rr_aa_02 = d_a(3)*x21
            rr2_rr_aa(1, 3) = rr2_rr_aa(1, 3) + t_rr2_rr_aa_02
            rr2_rr_aa(3, 1) = rr2_rr_aa(3, 1) + t_rr2_rr_aa_02
            rr2_rr_aa(2, 2) = rr2_rr_aa(2, 2) + (x9*(-x1*x14 + x1*x15 + x1*x16 + x1*x18 + x19))
            t_rr2_rr_aa_12 = d_a(2)*d_a(3)*x20*x9
            rr2_rr_aa(2, 3) = rr2_rr_aa(2, 3) + t_rr2_rr_aa_12
            rr2_rr_aa(3, 2) = rr2_rr_aa(3, 2) + t_rr2_rr_aa_12
            rr2_rr_aa(3, 3) = rr2_rr_aa(3, 3) + (x9*(-x14*x2 + x15*x2 + x16*x2 + x18*x2 + x19))
         end block
      end select

   end subroutine cfc_atomic_radius2_eval

   !> Accumulate the uncontracted two-*radius* derivative of the spatial ones.
