   !> Accumulate the uncontracted mixed nuclear-radius derivative.
   !>
   !> For each ordered pair of centers (A, B) this atom can supply,
   !>
   !>    mx{k}_AB(i1..ik, beta) = d2/(dr_A,beta dRad_B)  d^k K / dr_i1..dr_ik
   !>
   !> The first slot letter names the center of the *position* derivative, the
   !> second the center of the *radius* derivative.  Those are different kinds of
   !> derivative, so the pair term emits all four combinations rather than three:
   !> `_ab` and `_ba` are distinct expressions, not transposes of one another.
   !>
   !> `cfc_nucrad_eval` lifts these into `f2_rA_rad`, `f3_r_rA_rad` and
   !> `f4_rr_rA_rad`.  The nuclear sign is already applied.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    a1         Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..2); a larger value
   !>                          is treated as 2
   !> @param[inout] mx0_aa     d2/(dr_a dR_a) of the order-0 spatial derivative, position on atom a
   !>                          and radius on atom a; trailing index is a's nuclear component
   !> @param[inout] mx1_r_aa   d2/(dr_a dR_a) of the order-1 spatial derivative, position on atom a
   !>                          and radius on atom a; trailing index is a's nuclear component
   !> @param[inout] mx2_rr_aa  d2/(dr_a dR_a) of the order-2 spatial derivative, position on atom a
   !>                          and radius on atom a; trailing index is a's nuclear component
   pure subroutine cfc_atomic_nucrad_eval(d_a, R_a, a1, max_deriv, mx0_aa, mx1_r_aa, mx2_rr_aa)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Highest spatial-derivative order to accumulate (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dr_a dR_a) of the order-0 spatial derivative, position on atom a and radius on atom a;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx0_aa(3)
      !> d2/(dr_a dR_a) of the order-1 spatial derivative, position on atom a and radius on atom a;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx1_r_aa(3, 3)
      !> d2/(dr_a dR_a) of the order-2 spatial derivative, position on atom a and radius on atom a;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx2_rr_aa(3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x1 = exp(a1*(-1.0_wp + x0/R_a))
            x2 = d_a(1)*x1
            x3 = (a1*a1)/(R_a*R_a*R_a)
            x4 = a1/((R_a*R_a)*x0)
            x5 = x1*x3
            x6 = x1*x4
            mx0_aa(1) = mx0_aa(1) + (x2*x3 + x2*x4)
            mx0_aa(2) = mx0_aa(2) + (d_a(2)*x5 + d_a(2)*x6)
            mx0_aa(3) = mx0_aa(3) + (d_a(3)*x5 + d_a(3)*x6)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = exp(a1*(-1.0_wp + x4/R_a))
            x6 = (a1*a1)*x5/(R_a*R_a*R_a)
            x7 = d_a(1)*x6
            x8 = x5/x4
            x9 = a1/(R_a*R_a)
            x10 = x8*x9
            x11 = d_a(2)*x6
            x12 = 1.0_wp/x3
            x13 = x12*x6
            x14 = (a1*a1*a1)*x8/(R_a*R_a*R_a*R_a)
            x15 = x5*x9/(x3*sqrt(x3))
            x16 = x10 + x6
            x17 = d_a(1)*d_a(2)
            x18 = x12*x7
            x19 = d_a(2)*x18 + x14*x17 - x15*x17
            x20 = d_a(1)*d_a(3)
            x21 = d_a(3)*x18 + x14*x20 - x15*x20
            x22 = d_a(2)*d_a(3)
            x23 = d_a(3)*x11*x12 + x14*x22 - x15*x22
            mx0_aa(1) = mx0_aa(1) + (d_a(1)*x10 + x7)
            mx0_aa(2) = mx0_aa(2) + (d_a(2)*x10 + x11)
            mx0_aa(3) = mx0_aa(3) + (d_a(3)*x10 + d_a(3)*x6)
            mx1_r_aa(1, 1) = mx1_r_aa(1, 1) + (x0*x13 + x0*x14 - x0*x15 + x16)
            mx1_r_aa(1, 2) = mx1_r_aa(1, 2) + (x19)
            mx1_r_aa(1, 3) = mx1_r_aa(1, 3) + (x21)
            mx1_r_aa(2, 1) = mx1_r_aa(2, 1) + (x19)
            mx1_r_aa(2, 2) = mx1_r_aa(2, 2) + (x1*x13 + x1*x14 - x1*x15 + x16)
            mx1_r_aa(2, 3) = mx1_r_aa(2, 3) + (x23)
            mx1_r_aa(3, 1) = mx1_r_aa(3, 1) + (x21)
            mx1_r_aa(3, 2) = mx1_r_aa(3, 2) + (x23)
            mx1_r_aa(3, 3) = mx1_r_aa(3, 3) + (x13*x2 + x14*x2 - x15*x2 + x16)
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, t_mx2_rr_aa_010, t_mx2_rr_aa_011, t_mx2_rr_aa_012
            real(wp) :: t_mx2_rr_aa_020, t_mx2_rr_aa_021, t_mx2_rr_aa_022, t_mx2_rr_aa_120
            real(wp) :: t_mx2_rr_aa_121, t_mx2_rr_aa_122

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = exp(a1*(-1.0_wp + x4/R_a))
            x6 = (a1*a1)*x5/(R_a*R_a*R_a)
            x7 = d_a(1)*x6
            x8 = x5/x4
            x9 = a1/(R_a*R_a)
            x10 = x8*x9
            x11 = d_a(2)*x6
            x12 = d_a(3)*x6
            x13 = 1.0_wp/x3
            x14 = x13*x6
            x15 = (a1*a1*a1)*x8/(R_a*R_a*R_a*R_a)
            x16 = x5*x9
            x17 = x16/(x3*sqrt(x3))
            x18 = x10 + x6
            x19 = d_a(2)*x17
            x20 = d_a(2)*x15
            x21 = x13*x7
            x22 = -d_a(1)*x19 + d_a(1)*x20 + d_a(2)*x21
            x23 = d_a(3)*x17
            x24 = d_a(3)*x15
            x25 = -d_a(1)*x23 + d_a(1)*x24 + d_a(3)*x21
            x26 = x11*x13
            x27 = -d_a(3)*x19 + d_a(3)*x20 + d_a(3)*x26
            x28 = d_a(1)*x17
            x29 = d_a(1)*x15
            x30 = (d_a(1)*d_a(1)*d_a(1))
            x31 = 3.0_wp*x30
            x32 = x16/(x3*x3*sqrt(x3))
            x33 = (a1*a1*a1*a1)*x13*x5/(R_a*R_a*R_a*R_a*R_a)
            x34 = 1.0_wp/(x3*x3)
            x35 = x34*x6
            x36 = x0*x33
            x37 = 3.0_wp*x0
            x38 = x34*x37
            x39 = x32*x37
            x40 = -x19 + x20 + x26
            x41 = d_a(2)*x36 + d_a(2)*x39 - x11*x38 + x40
            x42 = x12*x13
            x43 = -x23 + x24 + x42
            x44 = d_a(3)*x36 + d_a(3)*x39 - x12*x38 + x43
            x45 = d_a(1)*x33
            x46 = 3.0_wp*x1
            x47 = x34*x7
            x48 = d_a(1)*x32
            x49 = x21 - x28 + x29
            x50 = x1*x45 - x46*x47 + x46*x48 + x49
            x51 = d_a(2)*d_a(3)
            x52 = 3.0_wp*x51
            x53 = x45*x51 - x47*x52 + x48*x52
            x54 = 3.0_wp*x2
            x55 = x2*x45 - x47*x54 + x48*x54 + x49
            x56 = (d_a(2)*d_a(2)*d_a(2))
            x57 = 3.0_wp*x56
            x58 = d_a(3)*x1
            x59 = 3.0_wp*x32
            x60 = -x12*x34*x46 + x33*x58 + x43 + x58*x59
            x61 = d_a(2)*x2
            x62 = -x11*x34*x54 + x33*x61 + x40 + x59*x61
            x63 = (d_a(3)*d_a(3)*d_a(3))
            x64 = 3.0_wp*x63
            mx0_aa(1) = mx0_aa(1) + (d_a(1)*x10 + x7)
            mx0_aa(2) = mx0_aa(2) + (d_a(2)*x10 + x11)
            mx0_aa(3) = mx0_aa(3) + (d_a(3)*x10 + x12)
            mx1_r_aa(1, 1) = mx1_r_aa(1, 1) + (x0*x14 + x0*x15 - x0*x17 + x18)
            mx1_r_aa(1, 2) = mx1_r_aa(1, 2) + (x22)
            mx1_r_aa(1, 3) = mx1_r_aa(1, 3) + (x25)
            mx1_r_aa(2, 1) = mx1_r_aa(2, 1) + (x22)
            mx1_r_aa(2, 2) = mx1_r_aa(2, 2) + (x1*x14 + x1*x15 - x1*x17 + x18)
            mx1_r_aa(2, 3) = mx1_r_aa(2, 3) + (x27)
            mx1_r_aa(3, 1) = mx1_r_aa(3, 1) + (x25)
            mx1_r_aa(3, 2) = mx1_r_aa(3, 2) + (x27)
            mx1_r_aa(3, 3) = mx1_r_aa(3, 3) + (x14*x2 + x15*x2 - x17*x2 + x18)
            mx2_rr_aa(1, 1, 1) = &
               mx2_rr_aa(1, 1, 1) + (3.0_wp*x21 - 3.0_wp*x28 + 3.0_wp*x29 + x30*x33 + x31*x32 - &
               x31*x35)
            mx2_rr_aa(1, 1, 2) = mx2_rr_aa(1, 1, 2) + (x41)
            mx2_rr_aa(1, 1, 3) = mx2_rr_aa(1, 1, 3) + (x44)
            t_mx2_rr_aa_010 = x41
            mx2_rr_aa(1, 2, 1) = mx2_rr_aa(1, 2, 1) + t_mx2_rr_aa_010
            mx2_rr_aa(2, 1, 1) = mx2_rr_aa(2, 1, 1) + t_mx2_rr_aa_010
            t_mx2_rr_aa_011 = x50
            mx2_rr_aa(1, 2, 2) = mx2_rr_aa(1, 2, 2) + t_mx2_rr_aa_011
            mx2_rr_aa(2, 1, 2) = mx2_rr_aa(2, 1, 2) + t_mx2_rr_aa_011
            t_mx2_rr_aa_012 = x53
            mx2_rr_aa(1, 2, 3) = mx2_rr_aa(1, 2, 3) + t_mx2_rr_aa_012
            mx2_rr_aa(2, 1, 3) = mx2_rr_aa(2, 1, 3) + t_mx2_rr_aa_012
            t_mx2_rr_aa_020 = x44
            mx2_rr_aa(1, 3, 1) = mx2_rr_aa(1, 3, 1) + t_mx2_rr_aa_020
            mx2_rr_aa(3, 1, 1) = mx2_rr_aa(3, 1, 1) + t_mx2_rr_aa_020
            t_mx2_rr_aa_021 = x53
            mx2_rr_aa(1, 3, 2) = mx2_rr_aa(1, 3, 2) + t_mx2_rr_aa_021
            mx2_rr_aa(3, 1, 2) = mx2_rr_aa(3, 1, 2) + t_mx2_rr_aa_021
            t_mx2_rr_aa_022 = x55
            mx2_rr_aa(1, 3, 3) = mx2_rr_aa(1, 3, 3) + t_mx2_rr_aa_022
            mx2_rr_aa(3, 1, 3) = mx2_rr_aa(3, 1, 3) + t_mx2_rr_aa_022
            mx2_rr_aa(2, 2, 1) = mx2_rr_aa(2, 2, 1) + (x50)
            mx2_rr_aa(2, 2, 2) = &
               mx2_rr_aa(2, 2, 2) + (-3.0_wp*x19 + 3.0_wp*x20 + 3.0_wp*x26 + x32*x57 + x33*x56 - &
               x35*x57)
            mx2_rr_aa(2, 2, 3) = mx2_rr_aa(2, 2, 3) + (x60)
            t_mx2_rr_aa_120 = x53
            mx2_rr_aa(2, 3, 1) = mx2_rr_aa(2, 3, 1) + t_mx2_rr_aa_120
            mx2_rr_aa(3, 2, 1) = mx2_rr_aa(3, 2, 1) + t_mx2_rr_aa_120
            t_mx2_rr_aa_121 = x60
            mx2_rr_aa(2, 3, 2) = mx2_rr_aa(2, 3, 2) + t_mx2_rr_aa_121
            mx2_rr_aa(3, 2, 2) = mx2_rr_aa(3, 2, 2) + t_mx2_rr_aa_121
            t_mx2_rr_aa_122 = x62
            mx2_rr_aa(2, 3, 3) = mx2_rr_aa(2, 3, 3) + t_mx2_rr_aa_122
            mx2_rr_aa(3, 2, 3) = mx2_rr_aa(3, 2, 3) + t_mx2_rr_aa_122
            mx2_rr_aa(3, 3, 1) = mx2_rr_aa(3, 3, 1) + (x55)
            mx2_rr_aa(3, 3, 2) = mx2_rr_aa(3, 3, 2) + (x62)
            mx2_rr_aa(3, 3, 3) = &
               mx2_rr_aa(3, 3, 3) + (-3.0_wp*x23 + 3.0_wp*x24 + x32*x64 + x33*x63 - x35*x64 + &
               3.0_wp*x42)
         end block
      end select

   end subroutine cfc_atomic_nucrad_eval

   !> Accumulate the uncontracted mixed nuclear-radius derivative.
   !>
   !> For each ordered pair of centers (A, B) this pair can supply,
   !>
   !>    mx{k}_AB(i1..ik, beta) = d2/(dr_A,beta dRad_B)  d^k K / dr_i1..dr_ik
   !>
   !> The first slot letter names the center of the *position* derivative, the
   !> second the center of the *radius* derivative.  Those are different kinds of
   !> derivative, so the pair term emits all four combinations rather than three:
   !> `_ab` and `_ba` are distinct expressions, not transposes of one another.
   !>
   !> `cfc_nucrad_eval` lifts these into `f2_rA_rad`, `f3_r_rA_rad` and
   !> `f4_rr_rA_rad`.  The nuclear sign is already applied.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    d_b        Displacement r - r_b
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    R_b        Radius of atom b
   !> @param[in]    a2         Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
   !> @param[in]    c_par      Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..2); a larger value
   !>                          is treated as 2
   !> @param[inout] mx0_aa     d2/(dr_a dR_a) of the order-0 spatial derivative, position on atom a
   !>                          and radius on atom a; trailing index is a's nuclear component
   !> @param[inout] mx0_ab     d2/(dr_a dR_b) of the order-0 spatial derivative, position on atom a
   !>                          and radius on atom b; trailing index is a's nuclear component
   !> @param[inout] mx0_ba     d2/(dr_b dR_a) of the order-0 spatial derivative, position on atom b
   !>                          and radius on atom a; trailing index is b's nuclear component
   !> @param[inout] mx0_bb     d2/(dr_b dR_b) of the order-0 spatial derivative, position on atom b
   !>                          and radius on atom b; trailing index is b's nuclear component
   !> @param[inout] mx1_r_aa   d2/(dr_a dR_a) of the order-1 spatial derivative, position on atom a
   !>                          and radius on atom a; trailing index is a's nuclear component
   !> @param[inout] mx1_r_ab   d2/(dr_a dR_b) of the order-1 spatial derivative, position on atom a
   !>                          and radius on atom b; trailing index is a's nuclear component
   !> @param[inout] mx1_r_ba   d2/(dr_b dR_a) of the order-1 spatial derivative, position on atom b
   !>                          and radius on atom a; trailing index is b's nuclear component
   !> @param[inout] mx1_r_bb   d2/(dr_b dR_b) of the order-1 spatial derivative, position on atom b
   !>                          and radius on atom b; trailing index is b's nuclear component
   !> @param[inout] mx2_rr_aa  d2/(dr_a dR_a) of the order-2 spatial derivative, position on atom a
   !>                          and radius on atom a; trailing index is a's nuclear component
   !> @param[inout] mx2_rr_ab  d2/(dr_a dR_b) of the order-2 spatial derivative, position on atom a
   !>                          and radius on atom b; trailing index is a's nuclear component
   !> @param[inout] mx2_rr_ba  d2/(dr_b dR_a) of the order-2 spatial derivative, position on atom b
   !>                          and radius on atom a; trailing index is b's nuclear component
   !> @param[inout] mx2_rr_bb  d2/(dr_b dR_b) of the order-2 spatial derivative, position on atom b
   !>                          and radius on atom b; trailing index is b's nuclear component
   pure subroutine cfc_pair_nucrad_eval(d_a, d_b, R_a, R_b, a2, c_par, max_deriv, mx0_aa, mx0_ab, &
                                        mx0_ba, mx0_bb, mx1_r_aa, mx1_r_ab, mx1_r_ba, mx1_r_bb, &
                                        mx2_rr_aa, mx2_rr_ab, mx2_rr_ba, mx2_rr_bb)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Highest spatial-derivative order to accumulate (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dr_a dR_a) of the order-0 spatial derivative, position on atom a and radius on atom a;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx0_aa(3)
      !> d2/(dr_a dR_b) of the order-0 spatial derivative, position on atom a and radius on atom b;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx0_ab(3)
      !> d2/(dr_b dR_a) of the order-0 spatial derivative, position on atom b and radius on atom a;
      !> trailing index is b's nuclear component
      real(wp), intent(inout) :: mx0_ba(3)
      !> d2/(dr_b dR_b) of the order-0 spatial derivative, position on atom b and radius on atom b;
      !> trailing index is b's nuclear component
      real(wp), intent(inout) :: mx0_bb(3)
      !> d2/(dr_a dR_a) of the order-1 spatial derivative, position on atom a and radius on atom a;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx1_r_aa(3, 3)
      !> d2/(dr_a dR_b) of the order-1 spatial derivative, position on atom a and radius on atom b;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx1_r_ab(3, 3)
      !> d2/(dr_b dR_a) of the order-1 spatial derivative, position on atom b and radius on atom a;
      !> trailing index is b's nuclear component
      real(wp), intent(inout) :: mx1_r_ba(3, 3)
      !> d2/(dr_b dR_b) of the order-1 spatial derivative, position on atom b and radius on atom b;
      !> trailing index is b's nuclear component
      real(wp), intent(inout) :: mx1_r_bb(3, 3)
      !> d2/(dr_a dR_a) of the order-2 spatial derivative, position on atom a and radius on atom a;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx2_rr_aa(3, 3, 3)
      !> d2/(dr_a dR_b) of the order-2 spatial derivative, position on atom a and radius on atom b;
      !> trailing index is a's nuclear component
      real(wp), intent(inout) :: mx2_rr_ab(3, 3, 3)
      !> d2/(dr_b dR_a) of the order-2 spatial derivative, position on atom b and radius on atom a;
      !> trailing index is b's nuclear component
      real(wp), intent(inout) :: mx2_rr_ba(3, 3, 3)
      !> d2/(dr_b dR_b) of the order-2 spatial derivative, position on atom b and radius on atom b;
      !> trailing index is b's nuclear component
      real(wp), intent(inout) :: mx2_rr_bb(3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68

            x0 = (a2*a2)
            x1 = 1.0_wp/R_a
            x2 = 1.0_wp/R_b
            x3 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
            x4 = x2*x3
            x5 = -x1*x4 + 1.0_wp
            x6 = (x5*x5*x5*x5)
            x7 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x8 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x9 = exp(a2*(x1*x7 + x2*x8 - 2.0_wp))
            x10 = c_par*x9
            x11 = x10*x6
            x12 = x0*x11
            x13 = 1.0_wp/(R_a*R_a*R_a)
            x14 = d_a(1)*x13
            x15 = 1.0_wp/(R_a*R_a)
            x16 = x15*x2
            x17 = d_b(1)*x10
            x18 = 4.0_wp*(x5*x5*x5)
            x19 = x17*x18
            x20 = d_a(1)*x15
            x21 = 1.0_wp/x7
            x22 = a2*x11
            x23 = x21*x22
            x24 = (x5*x5)
            x25 = 12.0_wp*x24
            x26 = 1.0_wp/(R_b*R_b)
            x27 = x26*x3
            x28 = x13*x27
