   !> Accumulate the *radius half* of the nuclear directional derivative.
   !>
   !> Given one radius direction per atom, this ADDS
   !>
   !>    tg{k}(i1..ik) += sum_A vr_A  d/dR_A  d^k K / dr_i1..dr_ik
   !>
   !> into the same `tg*` accumulators `*_tangent_eval` fills with the position
   !> half.  Together the two make the joint contraction
   !> ``sum_A (v_A . d/dr_A + vr_A d/dR_A)``, which is what `cfc_tangent_eval`
   !> and `cfc_hvp_eval` consume; the lift algebra is identical either way,
   !> because both halves land in the same family.
   !>
   !> Split rather than fused on purpose.  This layer is an O(n**2) pair loop
   !> run at every grid point, and the common caller holds its radii fixed:
   !> fusing would charge that caller for terms it discards on every pair, and
   !> would perturb its results in the last bits by regrouping the CSE block.
   !> A fixed-radius caller therefore simply never calls this routine.
   !>
   !> CALL EITHER THIS ROUTINE OR `*_radius_hvp_eval` FOR A GIVEN ATOM,
   !> NEVER BOTH -- that one fills the same `tg*` accumulators.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    a1         Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
   !> @param[in]    vr_a       Radius direction of atom a
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..3); a larger value
   !>                          is treated as 3
   !> @param[inout] tg0        sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the
   !>                          position half accumulated by the tangent/HVP routines
   !> @param[inout] tg1_r      sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the
   !>                          position half accumulated by the tangent/HVP routines
   !> @param[inout] tg2_rr     sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the
   !>                          position half accumulated by the tangent/HVP routines
   !> @param[inout] tg3_rrr    sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the
   !>                          position half accumulated by the tangent/HVP routines
   pure subroutine cfc_atomic_radius_tangent_eval(d_a, R_a, a1, vr_a, max_deriv, tg0, tg1_r, &
                                                  tg2_rr, tg3_rrr)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Radius direction of atom a
      real(wp), intent(in) :: vr_a
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg0
      !> sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            tg0 = tg0 + (-a1*vr_a*x0*exp(a1*(-1.0_wp + x0/R_a))/(R_a*R_a))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x1 = exp(a1*(-1.0_wp + x0/R_a))
            x2 = a1/(R_a*R_a)
            x3 = x1*x2
            x4 = d_a(1)*x1
            x5 = (a1*a1)/(R_a*R_a*R_a)
            x6 = 1.0_wp/x0
            x7 = x1*x5
            x8 = x3*x6
            tg0 = tg0 + (-vr_a*x0*x3)
            tg1_r(1) = tg1_r(1) + (vr_a*(-x2*x4*x6 - x4*x5))
            tg1_r(2) = tg1_r(2) + (vr_a*(-d_a(2)*x7 - d_a(2)*x8))
            tg1_r(3) = tg1_r(3) + (vr_a*(-d_a(3)*x7 - d_a(3)*x8))
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, t_tg2_rr_01, t_tg2_rr_02, t_tg2_rr_12

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = exp(a1*(-1.0_wp + x4/R_a))
            x6 = 1.0_wp/(R_a*R_a)
            x7 = a1*x6
            x8 = (a1*a1)*x5/(R_a*R_a*R_a)
            x9 = d_a(1)*x8
            x10 = x5/x4
            x11 = x10*x7
            x12 = d_a(2)*x8
            x13 = 1.0_wp/x3
            x14 = x13*x8
            x15 = (a1*a1*a1)*x10/(R_a*R_a*R_a*R_a)
            x16 = 1.0_wp/(x3*sqrt(x3))
            x17 = x11 + x8
            x18 = x13*x9
            tg0 = tg0 + (-vr_a*x4*x5*x7)
            tg1_r(1) = tg1_r(1) + (vr_a*(-d_a(1)*x11 - x9))
            tg1_r(2) = tg1_r(2) + (vr_a*(-d_a(2)*x11 - x12))
            tg1_r(3) = tg1_r(3) + (vr_a*(-d_a(3)*x11 - d_a(3)*x8))
            tg2_rr(1, 1) = tg2_rr(1, 1) + (vr_a*(a1*x0*x16*x5*x6 - x0*x14 - x0*x15 - x17))
            t_tg2_rr_01 = vr_a*(a1*d_a(1)*d_a(2)*x16*x5*x6 - d_a(1)*d_a(2)*x15 - d_a(2)*x18)
            tg2_rr(1, 2) = tg2_rr(1, 2) + t_tg2_rr_01
            tg2_rr(2, 1) = tg2_rr(2, 1) + t_tg2_rr_01
            t_tg2_rr_02 = vr_a*(a1*d_a(1)*d_a(3)*x16*x5*x6 - d_a(1)*d_a(3)*x15 - d_a(3)*x18)
            tg2_rr(1, 3) = tg2_rr(1, 3) + t_tg2_rr_02
            tg2_rr(3, 1) = tg2_rr(3, 1) + t_tg2_rr_02
            tg2_rr(2, 2) = tg2_rr(2, 2) + (vr_a*(a1*x1*x16*x5*x6 - x1*x14 - x1*x15 - x17))
            t_tg2_rr_12 = vr_a*(a1*d_a(2)*d_a(3)*x16*x5*x6 - d_a(2)*d_a(3)*x15 - d_a(3)*x12*x13)
            tg2_rr(2, 3) = tg2_rr(2, 3) + t_tg2_rr_12
            tg2_rr(3, 2) = tg2_rr(3, 2) + t_tg2_rr_12
            tg2_rr(3, 3) = tg2_rr(3, 3) + (vr_a*(a1*x16*x2*x5*x6 - x14*x2 - x15*x2 - x17))
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, t_tg2_rr_01
            real(wp) :: t_tg2_rr_02, t_tg2_rr_12, t_tg3_rrr_001, t_tg3_rrr_002, t_tg3_rrr_011
            real(wp) :: t_tg3_rrr_012, t_tg3_rrr_022, t_tg3_rrr_112, t_tg3_rrr_122

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = exp(a1*(-1.0_wp + x4/R_a))
            x6 = 1.0_wp/(R_a*R_a)
            x7 = a1*x6
            x8 = x5*x7
            x9 = 1.0_wp/(R_a*R_a*R_a)
            x10 = (a1*a1)
            x11 = x10*x5*x9
            x12 = d_a(1)*x11
            x13 = x5/x4
            x14 = x13*x7
            x15 = d_a(2)*x11
            x16 = d_a(3)*x11
            x17 = 1.0_wp/x3
            x18 = x11*x17
            x19 = (a1*a1*a1)*x13/(R_a*R_a*R_a*R_a)
            x20 = 1.0_wp/(x3*sqrt(x3))
            x21 = x11 + x14
            x22 = d_a(2)*x19
            x23 = x12*x17
            x24 = d_a(3)*x19
            x25 = x15*x17
            x26 = d_a(1)*x19
            x27 = (d_a(1)*d_a(1)*d_a(1))
            x28 = x8/(x3*x3*sqrt(x3))
            x29 = (a1*a1*a1*a1)*x17*x5/(R_a*R_a*R_a*R_a*R_a)
            x30 = 1.0_wp/(x3*x3)
            x31 = x0*x29
            x32 = 3.0_wp*x0*x28
            x33 = -a1*d_a(2)*x20*x5*x6 + x22 + x25
            x34 = x16*x17
            x35 = -a1*d_a(3)*x20*x5*x6 + x24 + x34
            x36 = d_a(1)*x29
            x37 = d_a(1)*x28
            x38 = -a1*d_a(1)*x20*x5*x6 + x23 + x26
            x39 = d_a(2)*d_a(3)
            x40 = (d_a(2)*d_a(2)*d_a(2))
            x41 = d_a(3)*x1
            x42 = 3.0_wp*x28
            x43 = d_a(2)*x2
            x44 = (d_a(3)*d_a(3)*d_a(3))
            tg0 = tg0 + (-vr_a*x4*x8)
            tg1_r(1) = tg1_r(1) + (vr_a*(-d_a(1)*x14 - x12))
            tg1_r(2) = tg1_r(2) + (vr_a*(-d_a(2)*x14 - x15))
            tg1_r(3) = tg1_r(3) + (vr_a*(-d_a(3)*x14 - x16))
            tg2_rr(1, 1) = tg2_rr(1, 1) + (vr_a*(a1*x0*x20*x5*x6 - x0*x18 - x0*x19 - x21))
            t_tg2_rr_01 = vr_a*(a1*d_a(1)*d_a(2)*x20*x5*x6 - d_a(1)*x22 - d_a(2)*x23)
            tg2_rr(1, 2) = tg2_rr(1, 2) + t_tg2_rr_01
            tg2_rr(2, 1) = tg2_rr(2, 1) + t_tg2_rr_01
            t_tg2_rr_02 = vr_a*(a1*d_a(1)*d_a(3)*x20*x5*x6 - d_a(1)*x24 - d_a(3)*x23)
            tg2_rr(1, 3) = tg2_rr(1, 3) + t_tg2_rr_02
            tg2_rr(3, 1) = tg2_rr(3, 1) + t_tg2_rr_02
            tg2_rr(2, 2) = tg2_rr(2, 2) + (vr_a*(a1*x1*x20*x5*x6 - x1*x18 - x1*x19 - x21))
            t_tg2_rr_12 = vr_a*(a1*d_a(2)*d_a(3)*x20*x5*x6 - d_a(3)*x22 - d_a(3)*x25)
            tg2_rr(2, 3) = tg2_rr(2, 3) + t_tg2_rr_12
            tg2_rr(3, 2) = tg2_rr(3, 2) + t_tg2_rr_12
            tg2_rr(3, 3) = tg2_rr(3, 3) + (vr_a*(a1*x2*x20*x5*x6 - x18*x2 - x19*x2 - x21))
            tg3_rrr(1, 1, 1) = &
               tg3_rrr(1, 1, 1) + (vr_a*(3.0_wp*a1*d_a(1)*x20*x5*x6 + 3.0_wp*x10*x27*x30*x5*x9 - &
               3.0_wp*x23 - 3.0_wp*x26 - 3.0_wp*x27*x28 - x27*x29))
            t_tg3_rrr_001 = vr_a*(3.0_wp*d_a(2)*x0*x10*x30*x5*x9 - d_a(2)*x31 - d_a(2)*x32 - x33)
            tg3_rrr(1, 1, 2) = tg3_rrr(1, 1, 2) + t_tg3_rrr_001
            tg3_rrr(1, 2, 1) = tg3_rrr(1, 2, 1) + t_tg3_rrr_001
            tg3_rrr(2, 1, 1) = tg3_rrr(2, 1, 1) + t_tg3_rrr_001
            t_tg3_rrr_002 = vr_a*(3.0_wp*d_a(3)*x0*x10*x30*x5*x9 - d_a(3)*x31 - d_a(3)*x32 - x35)
            tg3_rrr(1, 1, 3) = tg3_rrr(1, 1, 3) + t_tg3_rrr_002
            tg3_rrr(1, 3, 1) = tg3_rrr(1, 3, 1) + t_tg3_rrr_002
            tg3_rrr(3, 1, 1) = tg3_rrr(3, 1, 1) + t_tg3_rrr_002
            t_tg3_rrr_011 = vr_a*(3.0_wp*d_a(1)*x1*x10*x30*x5*x9 - x1*x36 - 3.0_wp*x1*x37 - x38)
            tg3_rrr(1, 2, 2) = tg3_rrr(1, 2, 2) + t_tg3_rrr_011
            tg3_rrr(2, 1, 2) = tg3_rrr(2, 1, 2) + t_tg3_rrr_011
            tg3_rrr(2, 2, 1) = tg3_rrr(2, 2, 1) + t_tg3_rrr_011
            t_tg3_rrr_012 = &
               vr_a*(3.0_wp*d_a(1)*d_a(2)*d_a(3)*x10*x30*x5*x9 - x36*x39 - 3.0_wp*x37*x39)
            tg3_rrr(1, 2, 3) = tg3_rrr(1, 2, 3) + t_tg3_rrr_012
            tg3_rrr(1, 3, 2) = tg3_rrr(1, 3, 2) + t_tg3_rrr_012
            tg3_rrr(2, 1, 3) = tg3_rrr(2, 1, 3) + t_tg3_rrr_012
            tg3_rrr(2, 3, 1) = tg3_rrr(2, 3, 1) + t_tg3_rrr_012
            tg3_rrr(3, 1, 2) = tg3_rrr(3, 1, 2) + t_tg3_rrr_012
            tg3_rrr(3, 2, 1) = tg3_rrr(3, 2, 1) + t_tg3_rrr_012
            t_tg3_rrr_022 = vr_a*(3.0_wp*d_a(1)*x10*x2*x30*x5*x9 - x2*x36 - 3.0_wp*x2*x37 - x38)
            tg3_rrr(1, 3, 3) = tg3_rrr(1, 3, 3) + t_tg3_rrr_022
            tg3_rrr(3, 1, 3) = tg3_rrr(3, 1, 3) + t_tg3_rrr_022
            tg3_rrr(3, 3, 1) = tg3_rrr(3, 3, 1) + t_tg3_rrr_022
            tg3_rrr(2, 2, 2) = &
               tg3_rrr(2, 2, 2) + (vr_a*(3.0_wp*a1*d_a(2)*x20*x5*x6 + 3.0_wp*x10*x30*x40*x5*x9 - &
               3.0_wp*x22 - 3.0_wp*x25 - 3.0_wp*x28*x40 - x29*x40))
            t_tg3_rrr_112 = vr_a*(3.0_wp*d_a(3)*x1*x10*x30*x5*x9 - x29*x41 - x35 - x41*x42)
            tg3_rrr(2, 2, 3) = tg3_rrr(2, 2, 3) + t_tg3_rrr_112
            tg3_rrr(2, 3, 2) = tg3_rrr(2, 3, 2) + t_tg3_rrr_112
            tg3_rrr(3, 2, 2) = tg3_rrr(3, 2, 2) + t_tg3_rrr_112
            t_tg3_rrr_122 = vr_a*(3.0_wp*d_a(2)*x10*x2*x30*x5*x9 - x29*x43 - x33 - x42*x43)
            tg3_rrr(2, 3, 3) = tg3_rrr(2, 3, 3) + t_tg3_rrr_122
            tg3_rrr(3, 2, 3) = tg3_rrr(3, 2, 3) + t_tg3_rrr_122
            tg3_rrr(3, 3, 2) = tg3_rrr(3, 3, 2) + t_tg3_rrr_122
            tg3_rrr(3, 3, 3) = &
               tg3_rrr(3, 3, 3) + (vr_a*(3.0_wp*a1*d_a(3)*x20*x5*x6 + 3.0_wp*x10*x30*x44*x5*x9 - &
               3.0_wp*x24 - 3.0_wp*x28*x44 - x29*x44 - 3.0_wp*x34))
         end block
      end select

   end subroutine cfc_atomic_radius_tangent_eval

   !> Accumulate the *radius half* of the nuclear directional derivative.
   !>
   !> Given one radius direction per atom, this ADDS
   !>
   !>    tg{k}(i1..ik) += sum_A vr_A  d/dR_A  d^k K / dr_i1..dr_ik
   !>
   !> into the same `tg*` accumulators `*_tangent_eval` fills with the position
   !> half.  Together the two make the joint contraction
   !> ``sum_A (v_A . d/dr_A + vr_A d/dR_A)``, which is what `cfc_tangent_eval`
   !> and `cfc_hvp_eval` consume; the lift algebra is identical either way,
   !> because both halves land in the same family.
   !>
   !> Split rather than fused on purpose.  This layer is an O(n**2) pair loop
   !> run at every grid point, and the common caller holds its radii fixed:
   !> fusing would charge that caller for terms it discards on every pair, and
   !> would perturb its results in the last bits by regrouping the CSE block.
   !> A fixed-radius caller therefore simply never calls this routine.
   !>
   !> CALL EITHER THIS ROUTINE OR `*_radius_hvp_eval` FOR A GIVEN PAIR,
   !> NEVER BOTH -- that one fills the same `tg*` accumulators.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    d_b        Displacement r - r_b
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    R_b        Radius of atom b
   !> @param[in]    a2         Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
   !> @param[in]    c_par      Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
   !> @param[in]    vr_a       Radius direction of atom a
   !> @param[in]    vr_b       Radius direction of atom b
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..3); a larger value
   !>                          is treated as 3
   !> @param[inout] tg0        sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the
   !>                          position half accumulated by the tangent/HVP routines
   !> @param[inout] tg1_r      sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the
   !>                          position half accumulated by the tangent/HVP routines
   !> @param[inout] tg2_rr     sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the
   !>                          position half accumulated by the tangent/HVP routines
   !> @param[inout] tg3_rrr    sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the
   !>                          position half accumulated by the tangent/HVP routines
   pure subroutine cfc_pair_radius_tangent_eval(d_a, d_b, R_a, R_b, a2, c_par, vr_a, vr_b, &
                                                max_deriv, tg0, tg1_r, tg2_rr, tg3_rrr)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Radius direction of atom a
      real(wp), intent(in) :: vr_a
      !> Radius direction of atom b
      real(wp), intent(in) :: vr_b
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg0
      !> sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x1 = 1.0_wp/(R_a*R_a)
            x2 = 1.0_wp/R_a
            x3 = 1.0_wp/R_b
            x4 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x5 = exp(a2*(x0*x2 + x3*x4 - 2.0_wp))
            x6 = c_par*x5
            x7 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
            x8 = -x2*x3*x7 + 1.0_wp
            x9 = a2*(x8*x8*x8*x8)
            x10 = (x8*x8*x8)
            x11 = 1.0_wp/(R_b*R_b)
            tg0 = &
               tg0 + (vr_a*(4.0_wp*c_par*x1*x10*x3*x5*x7 - x0*x1*x6*x9) + &
               vr_b*(4.0_wp*c_par*x10*x11*x2*x5*x7 - x11*x4*x6*x9))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61

            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x1 = 1.0_wp/(R_a*R_a)
            x2 = 1.0_wp/R_a
            x3 = 1.0_wp/R_b
            x4 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
            x5 = x3*x4
            x6 = -x2*x5 + 1.0_wp
            x7 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x8 = exp(a2*(x0*x2 + x3*x7 - 2.0_wp))
            x9 = c_par*x8
            x10 = (x6*x6*x6*x6)*x9
            x11 = a2*x10
            x12 = x1*x11
            x13 = (x6*x6*x6)
            x14 = 1.0_wp/(R_b*R_b)
