   !> Accumulate everything the joint position/radius Hessian adds to `*_hvp_eval`.
   !>
   !> Three ladders, sharing one CSE block because they share their radius
   !> derivatives.  Two are *corrections* -- they add the radius half of a
   !> contraction whose position half `*_hvp_eval` already accumulated:
   !>
   !>    tg{k}(i1..ik)         += sum_B vr_B d/dR_B  d^k K / dr^k
   !>    hvp{k}_A(i1..ik, beta) += sum_B vr_B d^2/(dr_A,beta dR_B)  d^k K / dr^k
   !>
   !> The third is complete in itself, the retained-radius row of the joint
   !> Hessian, and so carries both halves of its own contraction:
   !>
   !>    rh{k}_A(i1..ik) = sum_B (v_B . d/dr_B + vr_B d/dR_B)
   !>                        d/dR_A  d^k K / dr_i1..dr_ik
   !>
   !> A joint-Hessian caller therefore leaves its existing per-ATOM calls
   !> untouched and adds exactly one more.  The `tg*` ladder runs to spatial
   !> order 3, the `hvp*` and `rh*` ladders to 2 (their total order is one
   !> higher), all capped by ``max_deriv``.
   !>
   !> Fusing the three was measured, not assumed: the top pair branch needs 6111
   !> temporaries together against 4427 + 2230 for the corrections and the `rh*`
   !> ladder computed apart.  A modest 8%, but it goes the right way, and every
   !> caller of this routine wants all three.
   !>
   !> CALL EITHER THIS ROUTINE OR `*_radius_tangent_eval` FOR A GIVEN ATOM,
   !> NEVER BOTH -- both fill the `tg*` accumulators.
   !>
   !> @param[in]    d_a        Displacement r - r_a
   !> @param[in]    R_a        Radius of atom a
   !> @param[in]    a1         Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
   !> @param[in]    v_a        Nuclear displacement direction of atom a
   !> @param[in]    vr_a       Radius direction of atom a
   !> @param[in]    max_deriv  Highest spatial-derivative order to accumulate (0..3); a larger value
   !>                          is treated as 3
   !> @param[inout] tg0        sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the
   !>                          position half accumulated by cfc_atomic_hvp_eval
   !> @param[inout] tg1_r      sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the
   !>                          position half accumulated by cfc_atomic_hvp_eval
   !> @param[inout] tg2_rr     sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the
   !>                          position half accumulated by cfc_atomic_hvp_eval
   !> @param[inout] tg3_rrr    sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the
   !>                          position half accumulated by cfc_atomic_hvp_eval
   !> @param[inout] hvp0_a     sum_B vr_B d2/(dr_a dR_B) of the order-0 spatial derivative, *added*
   !>                          to the position half; trailing index is the retained nuclear
   !>                          component of atom a
   !> @param[inout] hvp1_r_a   sum_B vr_B d2/(dr_a dR_B) of the order-1 spatial derivative, *added*
   !>                          to the position half; trailing index is the retained nuclear
   !>                          component of atom a
   !> @param[inout] hvp2_rr_a  sum_B vr_B d2/(dr_a dR_B) of the order-2 spatial derivative, *added*
   !>                          to the position half; trailing index is the retained nuclear
   !>                          component of atom a
   !> @param[inout] rh0_a      sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-0 spatial
   !>                          derivative; complete, not a correction
   !> @param[inout] rh1_r_a    sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-1 spatial
   !>                          derivative; complete, not a correction
   !> @param[inout] rh2_rr_a   sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-2 spatial
   !>                          derivative; complete, not a correction
   pure subroutine cfc_atomic_radius_hvp_eval(d_a, R_a, a1, v_a, vr_a, max_deriv, tg0, tg1_r, &
                                              tg2_rr, tg3_rrr, hvp0_a, hvp1_r_a, hvp2_rr_a, &
                                              rh0_a, rh1_r_a, rh2_rr_a)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Nuclear displacement direction of atom a
      real(wp), intent(in) :: v_a(3)
      !> Radius direction of atom a
      real(wp), intent(in) :: vr_a
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the position half
      !> accumulated by cfc_atomic_hvp_eval
      real(wp), intent(inout) :: tg0
      !> sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the position half
      !> accumulated by cfc_atomic_hvp_eval
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the position half
      !> accumulated by cfc_atomic_hvp_eval
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the position half
      !> accumulated by cfc_atomic_hvp_eval
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-0 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp0_a(3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-1 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp1_r_a(3, 3)
      !> sum_B vr_B d2/(dr_a dR_B) of the order-2 spatial derivative, *added* to the position half;
      !> trailing index is the retained nuclear component of atom a
      real(wp), intent(inout) :: hvp2_rr_a(3, 3, 3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-0 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh0_a
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-1 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh1_r_a(3)
      !> sum_B (v_B . d/dr_B + vr_B d/dR_B) of d/dR_a of the order-2 spatial derivative; complete,
      !> not a correction
      real(wp), intent(inout) :: rh2_rr_a(3, 3)

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13

            x0 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
            x1 = sqrt(x0)
            x2 = exp(a1*(-1.0_wp + x1/R_a))
            x3 = a1*x2/(R_a*R_a)
            x4 = 1.0_wp/(R_a*R_a*R_a)
            x5 = (a1*a1)*x2
            x6 = x4*x5
            x7 = d_a(1)*x6
            x8 = x3/x1
            x9 = d_a(1)*x8
            x10 = d_a(2)*x6
            x11 = d_a(2)*x8
            x12 = d_a(3)*x6
            x13 = d_a(3)*x8
            tg0 = tg0 + (-vr_a*x1*x3)
            hvp0_a(1) = hvp0_a(1) + (vr_a*(x7 + x9))
            hvp0_a(2) = hvp0_a(2) + (vr_a*(x10 + x11))
            hvp0_a(3) = hvp0_a(3) + (vr_a*(x12 + x13))
            rh0_a = &
               rh0_a + (v_a(1)*x7 + v_a(1)*x9 + v_a(2)*x10 + v_a(2)*x11 + v_a(3)*x12 + v_a(3)*x13 &
               + vr_a*(2.0_wp*a1*x1*x2*x4 + x0*x5/(R_a*R_a*R_a*R_a)))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = exp(a1*(-1.0_wp + x4/R_a))
            x6 = a1/(R_a*R_a)
            x7 = x5*x6
            x8 = 1.0_wp/(R_a*R_a*R_a)
            x9 = (a1*a1)*x5
            x10 = x8*x9
            x11 = d_a(1)*x10
            x12 = x5/x4
            x13 = x12*x6
            x14 = d_a(1)*x13
            x15 = x11 + x14
            x16 = d_a(2)*x10
            x17 = d_a(2)*x13
            x18 = x16 + x17
            x19 = d_a(3)*x10
            x20 = d_a(3)*x13
            x21 = x19 + x20
            x22 = 1.0_wp/x3
            x23 = x10*x22
            x24 = 1.0_wp/(R_a*R_a*R_a*R_a)
            x25 = (a1*a1*a1)
            x26 = x12*x24*x25
            x27 = x7/(x3*sqrt(x3))
            x28 = x10 + x13
            x29 = x0*x23 + x0*x26 - x0*x27 + x28
            x30 = d_a(1)*d_a(2)
            x31 = x11*x22
            x32 = d_a(2)*x31 + x26*x30 - x27*x30
            x33 = vr_a*x32
            x34 = d_a(1)*d_a(3)
            x35 = d_a(3)*x31 + x26*x34 - x27*x34
            x36 = vr_a*x35
            x37 = x1*x23 + x1*x26 - x1*x27 + x28
            x38 = d_a(2)*d_a(3)
            x39 = d_a(3)*x16*x22 + x26*x38 - x27*x38
            x40 = vr_a*x39
            x41 = x2*x23 + x2*x26 - x2*x27 + x28
            x42 = x24*x9
            x43 = x4*x5
            x44 = 2.0_wp*a1*x8
            x45 = 4.0_wp*x42
            x46 = x12*x44
            x47 = x25*x43/(R_a*R_a*R_a*R_a*R_a)
            x48 = -x32
            x49 = -x35
            x50 = -x39
            tg0 = tg0 + (-vr_a*x4*x7)
            tg1_r(1) = tg1_r(1) + (-vr_a*x15)
            tg1_r(2) = tg1_r(2) + (-vr_a*x18)
            tg1_r(3) = tg1_r(3) + (-vr_a*x21)
            hvp0_a(1) = hvp0_a(1) + (vr_a*x15)
            hvp0_a(2) = hvp0_a(2) + (vr_a*x18)
            hvp0_a(3) = hvp0_a(3) + (vr_a*x21)
            hvp1_r_a(1, 1) = hvp1_r_a(1, 1) + (vr_a*x29)
            hvp1_r_a(1, 2) = hvp1_r_a(1, 2) + (x33)
            hvp1_r_a(1, 3) = hvp1_r_a(1, 3) + (x36)
            hvp1_r_a(2, 1) = hvp1_r_a(2, 1) + (x33)
            hvp1_r_a(2, 2) = hvp1_r_a(2, 2) + (vr_a*x37)
            hvp1_r_a(2, 3) = hvp1_r_a(2, 3) + (x40)
            hvp1_r_a(3, 1) = hvp1_r_a(3, 1) + (x36)
            hvp1_r_a(3, 2) = hvp1_r_a(3, 2) + (x40)
            hvp1_r_a(3, 3) = hvp1_r_a(3, 3) + (vr_a*x41)
            rh0_a = &
               rh0_a + (v_a(1)*x11 + v_a(1)*x14 + v_a(2)*x16 + v_a(2)*x17 + v_a(3)*x19 + &
               v_a(3)*x20 + vr_a*(x3*x42 + x43*x44))
            rh1_r_a(1) = &
               rh1_r_a(1) + (v_a(1)*x29 - v_a(2)*x48 - v_a(3)*x49 + vr_a*(d_a(1)*x45 + d_a(1)*x46 &
               + d_a(1)*x47))
            rh1_r_a(2) = &
               rh1_r_a(2) + (-v_a(1)*x48 + v_a(2)*x37 - v_a(3)*x50 + vr_a*(d_a(2)*x45 + d_a(2)*x46 &
               + d_a(2)*x47))
            rh1_r_a(3) = &
               rh1_r_a(3) + (-v_a(1)*x49 - v_a(2)*x50 + v_a(3)*x41 + vr_a*(d_a(3)*x45 + d_a(3)*x46 &
               + d_a(3)*x47))
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93, x94, x95, x96, x97, x98, x99, x100, x101, x102, x103, x104, x105
            real(wp) :: x106, x107, x108, x109, x110, x111, x112, x113, x114, x115, x116, x117, x118
            real(wp) :: x119, x120, x121, x122, t_tg2_rr_01, t_tg2_rr_02, t_tg2_rr_12
            real(wp) :: t_hvp2_rr_a_010, t_hvp2_rr_a_011, t_hvp2_rr_a_012, t_hvp2_rr_a_020
            real(wp) :: t_hvp2_rr_a_021, t_hvp2_rr_a_022, t_hvp2_rr_a_120, t_hvp2_rr_a_121
            real(wp) :: t_hvp2_rr_a_122, t_rh2_rr_a_01, t_rh2_rr_a_02, t_rh2_rr_a_12

            x0 = 1.0_wp/(R_a*R_a)
            x1 = a1*x0
            x2 = (d_a(1)*d_a(1))
            x3 = (d_a(2)*d_a(2))
            x4 = (d_a(3)*d_a(3))
            x5 = x2 + x3 + x4
            x6 = sqrt(x5)
            x7 = exp(a1*(-1.0_wp + x6/R_a))
            x8 = x6*x7
            x9 = 1.0_wp/(R_a*R_a*R_a)
            x10 = (a1*a1)*x7
            x11 = x10*x9
            x12 = d_a(1)*x11
            x13 = x7/x6
            x14 = x1*x13
            x15 = d_a(1)*x14
            x16 = x12 + x15
            x17 = d_a(2)*x11
            x18 = d_a(2)*x14
            x19 = x17 + x18
            x20 = d_a(3)*x11
            x21 = d_a(3)*x14
            x22 = x20 + x21
            x23 = 1.0_wp/x5
            x24 = x11*x23
            x25 = x13*x2
            x26 = 1.0_wp/(R_a*R_a*R_a*R_a)
            x27 = (a1*a1*a1)
            x28 = x26*x27
            x29 = 1.0_wp/(x5*sqrt(x5))
            x30 = x11 + x14
            x31 = -a1*x0*x2*x29*x7 + x2*x24 + x25*x28 + x30
            x32 = -x31
            x33 = x13*x28
            x34 = d_a(2)*x33
            x35 = x12*x23
            x36 = -a1*d_a(1)*d_a(2)*x0*x29*x7 + d_a(1)*x34 + d_a(2)*x35
            x37 = -x36
            x38 = d_a(3)*x33
            x39 = -a1*d_a(1)*d_a(3)*x0*x29*x7 + d_a(1)*x38 + d_a(3)*x35
            x40 = -x39
            x41 = -a1*x0*x29*x3*x7 + x24*x3 + x3*x33 + x30
            x42 = -x41
            x43 = x17*x23
            x44 = -a1*d_a(2)*d_a(3)*x0*x29*x7 + d_a(3)*x34 + d_a(3)*x43
            x45 = -x44
            x46 = -a1*x0*x29*x4*x7 + x24*x4 + x30 + x33*x4
            x47 = -x46
            x48 = vr_a*x36
            x49 = vr_a*x39
            x50 = vr_a*x44
            x51 = x1*x29*x7
            x52 = d_a(1)*x51
            x53 = d_a(1)*x33
            x54 = (d_a(1)*d_a(1)*d_a(1))
            x55 = x54*x7
            x56 = 3.0_wp*x1/(x5*x5*sqrt(x5))
            x57 = 1.0_wp/(R_a*R_a*R_a*R_a*R_a)
            x58 = (a1*a1*a1*a1)
            x59 = x23*x57*x58
            x60 = 3.0_wp/(x5*x5)
            x61 = x11*x60
            x62 = 3.0_wp*x35 - 3.0_wp*x52 + 3.0_wp*x53 - x54*x61 + x55*x56 + x55*x59
            x63 = x2*x7
            x64 = x59*x63
            x65 = x2*x60
            x66 = x56*x63
            x67 = d_a(2)*x51
            x68 = x34 + x43 - x67
            x69 = d_a(2)*x64 + d_a(2)*x66 - x17*x65 + x68
            x70 = vr_a*x69
            x71 = x20*x23
            x72 = d_a(3)*x51
            x73 = x38 + x71 - x72
            x74 = d_a(3)*x64 + d_a(3)*x66 - x20*x65 + x73
            x75 = vr_a*x74
            x76 = x59*x7
            x77 = d_a(1)*x76
            x78 = x12*x60
            x79 = x56*x7
            x80 = d_a(1)*x79
            x81 = x35 - x52 + x53
            x82 = x3*x77 - x3*x78 + x3*x80 + x81
            x83 = vr_a*x82
            x84 = d_a(2)*d_a(3)
            x85 = x77*x84 - x78*x84 + x80*x84
            x86 = vr_a*x85
            x87 = x4*x77 - x4*x78 + x4*x80 + x81
            x88 = vr_a*x87
            x89 = (d_a(2)*d_a(2)*d_a(2))
            x90 = 3.0_wp*x34 + 3.0_wp*x43 - x61*x89 - 3.0_wp*x67 + x76*x89 + x79*x89
            x91 = d_a(3)*x3
            x92 = -x20*x3*x60 + x73 + x76*x91 + x79*x91
            x93 = vr_a*x92
            x94 = d_a(2)*x4
            x95 = -x17*x4*x60 + x68 + x76*x94 + x79*x94
            x96 = vr_a*x95
            x97 = (d_a(3)*d_a(3)*d_a(3))
            x98 = 3.0_wp*x38 - x61*x97 + 3.0_wp*x71 - 3.0_wp*x72 + x76*x97 + x79*x97
            x99 = x10*x26
            x100 = 2.0_wp*a1*x9
            x101 = 4.0_wp*x99
            x102 = x100*x13
            x103 = x27*x57
            x104 = x103*x8
            x105 = -x69
            x106 = -x74
            x107 = x58/(R_a*R_a*R_a*R_a*R_a*R_a)
            x108 = x100*x29
            x109 = 2.0_wp*x23*x99
            x110 = 5.0_wp*x103
            x111 = x101 + x102 + x104
            x112 = -x85
            x113 = x107*x7
            x114 = d_a(1)*x113
            x115 = x108*x7
            x116 = d_a(1)*d_a(2)
            x117 = x110*x13
            x118 = -x82
            x119 = d_a(1)*d_a(3)
            x120 = -x87
            x121 = -x92
            x122 = -x95
            tg0 = tg0 + (-vr_a*x1*x8)
            tg1_r(1) = tg1_r(1) + (-vr_a*x16)
            tg1_r(2) = tg1_r(2) + (-vr_a*x19)
            tg1_r(3) = tg1_r(3) + (-vr_a*x22)
            tg2_rr(1, 1) = tg2_rr(1, 1) + (vr_a*x32)
            t_tg2_rr_01 = vr_a*x37
            tg2_rr(1, 2) = tg2_rr(1, 2) + t_tg2_rr_01
            tg2_rr(2, 1) = tg2_rr(2, 1) + t_tg2_rr_01
            t_tg2_rr_02 = vr_a*x40
            tg2_rr(1, 3) = tg2_rr(1, 3) + t_tg2_rr_02
            tg2_rr(3, 1) = tg2_rr(3, 1) + t_tg2_rr_02
            tg2_rr(2, 2) = tg2_rr(2, 2) + (vr_a*x42)
            t_tg2_rr_12 = vr_a*x45
            tg2_rr(2, 3) = tg2_rr(2, 3) + t_tg2_rr_12
            tg2_rr(3, 2) = tg2_rr(3, 2) + t_tg2_rr_12
            tg2_rr(3, 3) = tg2_rr(3, 3) + (vr_a*x47)
            hvp0_a(1) = hvp0_a(1) + (vr_a*x16)
            hvp0_a(2) = hvp0_a(2) + (vr_a*x19)
            hvp0_a(3) = hvp0_a(3) + (vr_a*x22)
            hvp1_r_a(1, 1) = hvp1_r_a(1, 1) + (vr_a*x31)
            hvp1_r_a(1, 2) = hvp1_r_a(1, 2) + (x48)
            hvp1_r_a(1, 3) = hvp1_r_a(1, 3) + (x49)
