               x3010*x5941 + x3012*x5898 - x3012*x5902 + x3012*x5909 - x3012*x5917 + x3012*x5933 - &
               x3259*x3571*x5938 - x3571*x5920 + x3578*x5946 - x4*x5900 - x4*x5903 - x4*x5916 + &
               x4*x5932 - x4*x5937 + x4*x5944 - x4*x5987 + x4*x6050 + x4*x6052 + x4*x6055 - &
               x4068*x6075 + x4709*x5947 + x5865*x5899 - x5867*x5945 - x5904*x6074 + x5907*x6074 + &
               x5907*x6076 - x5915*x6076 - x5918*x779 - x5921*x6075 + x5929*x6074 - x5934*x6076 + &
               x5949 + x6051*x779) - x5515*x6033 - x5517*x6031 - x5518*x6062 - x5519*x6073 - &
               x5524*x6060 - x5527*x6072)
         end block
      end select

   end subroutine cfc_pair_radius_hvp_eval

   !> Lift the accumulated pseudo-density tensors to the level set.
   !>
   !> The CFC level set is ``S = -log PD``.  PD is a sum over atoms and pairs,
   !> so the log can only be taken once everything has been accumulated; this
   !> routine is that step, and it is O(1) -- call it once per evaluation point
   !> after the `*_term_eval` loops.
   !>
   !> Outputs are derivatives of ``S`` itself, sign included: the caller negates
   !> nothing.  (The previous `cfc_log_lift` returned derivatives of ``+log PD``
   !> and required the caller to negate.  The rename is deliberate, so that a
   !> stale call site fails to compile instead of flipping sign silently.)
   !>
   !> Every result is zeroed on entry, so a fully screened-out point (PD == 0)
   !> and the orders above `max_deriv` both come back as exact zeros; nothing
   !> this routine returns is ever left undefined.
   !>
   !> @param[in]    pd0        Accumulated order-0 spatial derivative of PD
   !> @param[in]    pd1_r      Accumulated order-1 spatial derivative of PD
   !> @param[in]    pd2_rr     Accumulated order-2 spatial derivative of PD
   !> @param[in]    pd3_rrr    Accumulated order-3 spatial derivative of PD
   !> @param[in]    pd4_rrrr   Accumulated order-4 spatial derivative of PD
   !> @param[in]    max_deriv  Highest derivative order to lift (0..4); a larger value is treated as
   !>                          4
   !> @param[out]   f0         Order-0 spatial derivative of the level set
   !> @param[out]   f1_r       Order-1 spatial derivative of the level set
   !> @param[out]   f2_rr      Order-2 spatial derivative of the level set
   !> @param[out]   f3_rrr     Order-3 spatial derivative of the level set
   !> @param[out]   f4_rrrr    Order-4 spatial derivative of the level set
   pure subroutine cfc_spatial_eval(pd0, pd1_r, pd2_rr, pd3_rrr, pd4_rrrr, max_deriv, f0, f1_r, &
                                    f2_rr, f3_rrr, f4_rrrr)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated order-3 spatial derivative of PD
      real(wp), intent(in) :: pd3_rrr(3, 3, 3)
      !> Accumulated order-4 spatial derivative of PD
      real(wp), intent(in) :: pd4_rrrr(3, 3, 3, 3)
      !> Highest derivative order to lift (0..4); a larger value is treated as 4
      integer, intent(in) :: max_deriv
      !> Order-0 spatial derivative of the level set
      real(wp), intent(out) :: f0
      !> Order-1 spatial derivative of the level set
      real(wp), intent(out) :: f1_r(3)
      !> Order-2 spatial derivative of the level set
      real(wp), intent(out) :: f2_rr(3, 3)
      !> Order-3 spatial derivative of the level set
      real(wp), intent(out) :: f3_rrr(3, 3, 3)
      !> Order-4 spatial derivative of the level set
      real(wp), intent(out) :: f4_rrrr(3, 3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      f0 = 0.0_wp
      f1_r = 0.0_wp
      f2_rr = 0.0_wp
      f3_rrr = 0.0_wp
      f4_rrrr = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            f0 = -log(pd0)
         end block
      case (1)
         block
            f0 = -log(pd0)
            f1_r(1) = -inv_pd*pd1_r(1)
            f1_r(2) = -inv_pd*pd1_r(2)
            f1_r(3) = -inv_pd*pd1_r(3)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, t_f2_rr_01, t_f2_rr_02, t_f2_rr_12

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            f0 = -log(pd0)
            f1_r(1) = -inv_pd*pd1_r(1)
            f1_r(2) = -inv_pd*pd1_r(2)
            f1_r(3) = -inv_pd*pd1_r(3)
            f2_rr(1, 1) = -inv_pd*pd2_rr(1, 1) + (pd1_r(1)*pd1_r(1))*x0
            t_f2_rr_01 = -inv_pd*pd2_rr(1, 2) + pd1_r(2)*x1
            f2_rr(1, 2) = t_f2_rr_01
            f2_rr(2, 1) = t_f2_rr_01
            t_f2_rr_02 = -inv_pd*pd2_rr(1, 3) + pd1_r(3)*x1
            f2_rr(1, 3) = t_f2_rr_02
            f2_rr(3, 1) = t_f2_rr_02
            f2_rr(2, 2) = -inv_pd*pd2_rr(2, 2) + (pd1_r(2)*pd1_r(2))*x0
            t_f2_rr_12 = -inv_pd*pd2_rr(2, 3) + pd1_r(2)*pd1_r(3)*x0
            f2_rr(2, 3) = t_f2_rr_12
            f2_rr(3, 2) = t_f2_rr_12
            f2_rr(3, 3) = -inv_pd*pd2_rr(3, 3) + (pd1_r(3)*pd1_r(3))*x0
         end block
      case (3)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, t_f2_rr_01, t_f2_rr_02, t_f2_rr_12, t_f3_rrr_001, t_f3_rrr_002
            real(wp) :: t_f3_rrr_011, t_f3_rrr_012, t_f3_rrr_022, t_f3_rrr_112, t_f3_rrr_122

            x0 = (inv_pd*inv_pd)
            x1 = (pd1_r(1)*pd1_r(1))
            x2 = pd1_r(1)*x0
            x3 = (pd1_r(2)*pd1_r(2))
            x4 = pd1_r(2)*pd1_r(3)
            x5 = (pd1_r(3)*pd1_r(3))
            x6 = 2.0_wp*pd1_r(1)
            x7 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
            x8 = pd2_rr(1, 1)*x0 - x1*x7
            x9 = pd2_rr(1, 2)*x0
            x10 = pd2_rr(1, 3)*x0
            x11 = pd2_rr(2, 2)*x0
            x12 = pd1_r(1)*x7
            x13 = -pd1_r(2)*x12 + pd2_rr(1, 2)*x0
            x14 = pd2_rr(2, 3)*x0
            x15 = pd2_rr(3, 3)*x0
            x16 = 2.0_wp*pd1_r(2)
            x17 = pd2_rr(2, 2)*x0 - x3*x7
            f0 = -log(pd0)
            f1_r(1) = -inv_pd*pd1_r(1)
            f1_r(2) = -inv_pd*pd1_r(2)
            f1_r(3) = -inv_pd*pd1_r(3)
            f2_rr(1, 1) = -inv_pd*pd2_rr(1, 1) + x0*x1
            t_f2_rr_01 = -inv_pd*pd2_rr(1, 2) + pd1_r(2)*x2
            f2_rr(1, 2) = t_f2_rr_01
            f2_rr(2, 1) = t_f2_rr_01
            t_f2_rr_02 = -inv_pd*pd2_rr(1, 3) + pd1_r(3)*x2
            f2_rr(1, 3) = t_f2_rr_02
            f2_rr(3, 1) = t_f2_rr_02
            f2_rr(2, 2) = -inv_pd*pd2_rr(2, 2) + x0*x3
            t_f2_rr_12 = -inv_pd*pd2_rr(2, 3) + x0*x4
            f2_rr(2, 3) = t_f2_rr_12
            f2_rr(3, 2) = t_f2_rr_12
            f2_rr(3, 3) = -inv_pd*pd2_rr(3, 3) + x0*x5
            f3_rrr(1, 1, 1) = -inv_pd*pd3_rrr(1, 1, 1) + pd1_r(1)*x8 + pd2_rr(1, 1)*x0*x6
            t_f3_rrr_001 = -inv_pd*pd3_rrr(1, 1, 2) + pd1_r(2)*x8 + x6*x9
            f3_rrr(1, 1, 2) = t_f3_rrr_001
            f3_rrr(1, 2, 1) = t_f3_rrr_001
            f3_rrr(2, 1, 1) = t_f3_rrr_001
            t_f3_rrr_002 = -inv_pd*pd3_rrr(1, 1, 3) + pd1_r(3)*x8 + x10*x6
            f3_rrr(1, 1, 3) = t_f3_rrr_002
            f3_rrr(1, 3, 1) = t_f3_rrr_002
            f3_rrr(3, 1, 1) = t_f3_rrr_002
            t_f3_rrr_011 = -inv_pd*pd3_rrr(1, 2, 2) + pd1_r(1)*x11 + pd1_r(2)*x13 + pd1_r(2)*x9
            f3_rrr(1, 2, 2) = t_f3_rrr_011
            f3_rrr(2, 1, 2) = t_f3_rrr_011
            f3_rrr(2, 2, 1) = t_f3_rrr_011
            t_f3_rrr_012 = -inv_pd*pd3_rrr(1, 2, 3) + pd1_r(1)*x14 + pd1_r(2)*x10 + pd1_r(3)*x13
            f3_rrr(1, 2, 3) = t_f3_rrr_012
            f3_rrr(1, 3, 2) = t_f3_rrr_012
            f3_rrr(2, 1, 3) = t_f3_rrr_012
            f3_rrr(2, 3, 1) = t_f3_rrr_012
            f3_rrr(3, 1, 2) = t_f3_rrr_012
            f3_rrr(3, 2, 1) = t_f3_rrr_012
            t_f3_rrr_022 = &
               -inv_pd*pd3_rrr(1, 3, 3) + pd1_r(1)*x15 + pd1_r(3)*x10 + pd1_r(3)*(-pd1_r(3)*x12 + &
               pd2_rr(1, 3)*x0)
            f3_rrr(1, 3, 3) = t_f3_rrr_022
            f3_rrr(3, 1, 3) = t_f3_rrr_022
            f3_rrr(3, 3, 1) = t_f3_rrr_022
            f3_rrr(2, 2, 2) = -inv_pd*pd3_rrr(2, 2, 2) + pd1_r(2)*x17 + x11*x16
            t_f3_rrr_112 = -inv_pd*pd3_rrr(2, 2, 3) + pd1_r(3)*x17 + x14*x16
            f3_rrr(2, 2, 3) = t_f3_rrr_112
            f3_rrr(2, 3, 2) = t_f3_rrr_112
            f3_rrr(3, 2, 2) = t_f3_rrr_112
            t_f3_rrr_122 = &
               -inv_pd*pd3_rrr(2, 3, 3) + pd1_r(2)*x15 + pd1_r(3)*x14 + pd1_r(3)*(pd2_rr(2, 3)*x0 &
               - x4*x7)
            f3_rrr(2, 3, 3) = t_f3_rrr_122
            f3_rrr(3, 2, 3) = t_f3_rrr_122
            f3_rrr(3, 3, 2) = t_f3_rrr_122
            f3_rrr(3, 3, 3) = &
               -inv_pd*pd3_rrr(3, 3, 3) + 2.0_wp*pd1_r(3)*x15 + pd1_r(3)*(pd2_rr(3, 3)*x0 - x5*x7)
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60
            real(wp) :: t_f2_rr_01, t_f2_rr_02, t_f2_rr_12, t_f3_rrr_001, t_f3_rrr_002, t_f3_rrr_011
            real(wp) :: t_f3_rrr_012, t_f3_rrr_022, t_f3_rrr_112, t_f3_rrr_122, t_f4_rrrr_0001
            real(wp) :: t_f4_rrrr_0002, t_f4_rrrr_0011, t_f4_rrrr_0012, t_f4_rrrr_0022
            real(wp) :: t_f4_rrrr_0111, t_f4_rrrr_0112, t_f4_rrrr_0122, t_f4_rrrr_0222
            real(wp) :: t_f4_rrrr_1112, t_f4_rrrr_1122, t_f4_rrrr_1222

            x0 = (inv_pd*inv_pd)
            x1 = (pd1_r(1)*pd1_r(1))
            x2 = pd1_r(1)*x0
            x3 = (pd1_r(2)*pd1_r(2))
            x4 = pd1_r(2)*pd1_r(3)
            x5 = (pd1_r(3)*pd1_r(3))
            x6 = 2.0_wp*pd1_r(1)
            x7 = (inv_pd*inv_pd*inv_pd)
            x8 = 2.0_wp*x7
            x9 = pd2_rr(1, 1)*x0 - x1*x8
            x10 = pd2_rr(1, 2)*x0
            x11 = pd2_rr(1, 3)*x0
            x12 = pd2_rr(2, 2)*x0
            x13 = pd1_r(1)*x8
            x14 = -pd1_r(2)*x13 + pd2_rr(1, 2)*x0
            x15 = pd2_rr(2, 3)*x0
            x16 = pd2_rr(3, 3)*x0
            x17 = -pd1_r(3)*x13 + pd2_rr(1, 3)*x0
            x18 = 2.0_wp*pd1_r(2)
            x19 = pd2_rr(2, 2)*x0 - x3*x8
            x20 = pd2_rr(2, 3)*x0 - x4*x8
            x21 = 2.0_wp*pd1_r(3)
            x22 = pd2_rr(3, 3)*x0 - x5*x8
            x23 = pd3_rrr(1, 1, 1)*x0
            x24 = 3.0_wp*pd1_r(1)
            x25 = 6.0_wp*x1
            x26 = 3.0_wp*pd2_rr(1, 1)*x0 - x25*x7
            x27 = 4.0_wp*x7
            x28 = pd1_r(1)*x27
            x29 = (inv_pd*inv_pd*inv_pd*inv_pd)
            x30 = -pd2_rr(1, 1)*x8 + x25*x29
            x31 = pd1_r(1)*x30 - pd2_rr(1, 1)*x28 + x23
            x32 = pd3_rrr(1, 1, 2)*x0
            x33 = pd3_rrr(1, 1, 3)*x0
            x34 = pd3_rrr(1, 2, 2)*x0
            x35 = -pd1_r(2)*x28 + 2.0_wp*pd2_rr(1, 2)*x0
            x36 = pd1_r(2)*x30 - pd2_rr(1, 2)*x28 + x32
            x37 = pd3_rrr(1, 2, 3)*x0
            x38 = pd3_rrr(1, 3, 3)*x0
            x39 = -pd1_r(3)*x28 + 2.0_wp*pd2_rr(1, 3)*x0
            x40 = pd3_rrr(2, 2, 2)*x0
            x41 = pd2_rr(2, 2)*x8
            x42 = pd2_rr(1, 2)*x8
            x43 = 6.0_wp*x29
            x44 = pd1_r(1)*x43
            x45 = pd1_r(2)*x44 - x42
            x46 = -pd1_r(1)*x41 - pd1_r(2)*x42 + pd1_r(2)*x45 + pd3_rrr(1, 2, 2)*x0
            x47 = pd3_rrr(2, 2, 3)*x0
            x48 = pd3_rrr(2, 3, 3)*x0
            x49 = pd2_rr(2, 3)*x8
            x50 = pd2_rr(1, 3)*x8
            x51 = pd3_rrr(3, 3, 3)*x0
            x52 = pd2_rr(3, 3)*x8
            x53 = 3.0_wp*pd1_r(2)
            x54 = 6.0_wp*x3
            x55 = 3.0_wp*pd2_rr(2, 2)*x0 - x54*x7
            x56 = pd1_r(2)*x27
            x57 = x29*x54 - x41
            x58 = pd1_r(2)*x57 - pd2_rr(2, 2)*x56 + x40
            x59 = 2.0_wp*pd2_rr(2, 3)*x0 - x27*x4
            x60 = 6.0_wp*x5
            f0 = -log(pd0)
            f1_r(1) = -inv_pd*pd1_r(1)
            f1_r(2) = -inv_pd*pd1_r(2)
            f1_r(3) = -inv_pd*pd1_r(3)
            f2_rr(1, 1) = -inv_pd*pd2_rr(1, 1) + x0*x1
            t_f2_rr_01 = -inv_pd*pd2_rr(1, 2) + pd1_r(2)*x2
            f2_rr(1, 2) = t_f2_rr_01
            f2_rr(2, 1) = t_f2_rr_01
            t_f2_rr_02 = -inv_pd*pd2_rr(1, 3) + pd1_r(3)*x2
            f2_rr(1, 3) = t_f2_rr_02
            f2_rr(3, 1) = t_f2_rr_02
            f2_rr(2, 2) = -inv_pd*pd2_rr(2, 2) + x0*x3
            t_f2_rr_12 = -inv_pd*pd2_rr(2, 3) + x0*x4
            f2_rr(2, 3) = t_f2_rr_12
            f2_rr(3, 2) = t_f2_rr_12
            f2_rr(3, 3) = -inv_pd*pd2_rr(3, 3) + x0*x5
            f3_rrr(1, 1, 1) = -inv_pd*pd3_rrr(1, 1, 1) + pd1_r(1)*x9 + pd2_rr(1, 1)*x0*x6
            t_f3_rrr_001 = -inv_pd*pd3_rrr(1, 1, 2) + 2.0_wp*pd1_r(1)*x10 + pd1_r(2)*x9
            f3_rrr(1, 1, 2) = t_f3_rrr_001
            f3_rrr(1, 2, 1) = t_f3_rrr_001
            f3_rrr(2, 1, 1) = t_f3_rrr_001
            t_f3_rrr_002 = -inv_pd*pd3_rrr(1, 1, 3) + 2.0_wp*pd1_r(1)*x11 + pd1_r(3)*x9
            f3_rrr(1, 1, 3) = t_f3_rrr_002
            f3_rrr(1, 3, 1) = t_f3_rrr_002
            f3_rrr(3, 1, 1) = t_f3_rrr_002
            t_f3_rrr_011 = -inv_pd*pd3_rrr(1, 2, 2) + pd1_r(1)*x12 + pd1_r(2)*x10 + pd1_r(2)*x14
            f3_rrr(1, 2, 2) = t_f3_rrr_011
            f3_rrr(2, 1, 2) = t_f3_rrr_011
            f3_rrr(2, 2, 1) = t_f3_rrr_011
            t_f3_rrr_012 = -inv_pd*pd3_rrr(1, 2, 3) + pd1_r(1)*x15 + pd1_r(2)*x11 + pd1_r(3)*x14
            f3_rrr(1, 2, 3) = t_f3_rrr_012
            f3_rrr(1, 3, 2) = t_f3_rrr_012
            f3_rrr(2, 1, 3) = t_f3_rrr_012
            f3_rrr(2, 3, 1) = t_f3_rrr_012
            f3_rrr(3, 1, 2) = t_f3_rrr_012
            f3_rrr(3, 2, 1) = t_f3_rrr_012
            t_f3_rrr_022 = -inv_pd*pd3_rrr(1, 3, 3) + pd1_r(1)*x16 + pd1_r(3)*x11 + pd1_r(3)*x17
            f3_rrr(1, 3, 3) = t_f3_rrr_022
            f3_rrr(3, 1, 3) = t_f3_rrr_022
            f3_rrr(3, 3, 1) = t_f3_rrr_022
            f3_rrr(2, 2, 2) = -inv_pd*pd3_rrr(2, 2, 2) + pd1_r(2)*x19 + x12*x18
            t_f3_rrr_112 = -inv_pd*pd3_rrr(2, 2, 3) + 2.0_wp*pd1_r(2)*x15 + pd1_r(3)*x19
            f3_rrr(2, 2, 3) = t_f3_rrr_112
            f3_rrr(2, 3, 2) = t_f3_rrr_112
            f3_rrr(3, 2, 2) = t_f3_rrr_112
            t_f3_rrr_122 = -inv_pd*pd3_rrr(2, 3, 3) + pd1_r(2)*x16 + pd1_r(3)*x15 + pd1_r(3)*x20
            f3_rrr(2, 3, 3) = t_f3_rrr_122
            f3_rrr(3, 2, 3) = t_f3_rrr_122
            f3_rrr(3, 3, 2) = t_f3_rrr_122
            f3_rrr(3, 3, 3) = -inv_pd*pd3_rrr(3, 3, 3) + pd1_r(3)*x22 + x16*x21
            f4_rrrr(1, 1, 1, 1) = &
               -inv_pd*pd4_rrrr(1, 1, 1, 1) + pd1_r(1)*x31 + pd2_rr(1, 1)*x26 + x23*x24
            t_f4_rrrr_0001 = &
               -inv_pd*pd4_rrrr(1, 1, 1, 2) + pd1_r(2)*x31 + pd2_rr(1, 2)*x26 + x24*x32
            f4_rrrr(1, 1, 1, 2) = t_f4_rrrr_0001
            f4_rrrr(1, 1, 2, 1) = t_f4_rrrr_0001
            f4_rrrr(1, 2, 1, 1) = t_f4_rrrr_0001
            f4_rrrr(2, 1, 1, 1) = t_f4_rrrr_0001
            t_f4_rrrr_0002 = &
               -inv_pd*pd4_rrrr(1, 1, 1, 3) + pd1_r(3)*x31 + pd2_rr(1, 3)*x26 + x24*x33
            f4_rrrr(1, 1, 1, 3) = t_f4_rrrr_0002
            f4_rrrr(1, 1, 3, 1) = t_f4_rrrr_0002
            f4_rrrr(1, 3, 1, 1) = t_f4_rrrr_0002
            f4_rrrr(3, 1, 1, 1) = t_f4_rrrr_0002
            t_f4_rrrr_0011 = &
               -inv_pd*pd4_rrrr(1, 1, 2, 2) + pd1_r(2)*x32 + pd1_r(2)*x36 + pd2_rr(1, 2)*x35 + &
               pd2_rr(2, 2)*x9 + x34*x6
            f4_rrrr(1, 1, 2, 2) = t_f4_rrrr_0011
            f4_rrrr(1, 2, 1, 2) = t_f4_rrrr_0011
            f4_rrrr(1, 2, 2, 1) = t_f4_rrrr_0011
            f4_rrrr(2, 1, 1, 2) = t_f4_rrrr_0011
            f4_rrrr(2, 1, 2, 1) = t_f4_rrrr_0011
            f4_rrrr(2, 2, 1, 1) = t_f4_rrrr_0011
            t_f4_rrrr_0012 = &
               -inv_pd*pd4_rrrr(1, 1, 2, 3) + pd1_r(2)*x33 + pd1_r(3)*x36 + pd2_rr(1, 3)*x35 + &
               pd2_rr(2, 3)*x9 + x37*x6
            f4_rrrr(1, 1, 2, 3) = t_f4_rrrr_0012
            f4_rrrr(1, 1, 3, 2) = t_f4_rrrr_0012
            f4_rrrr(1, 2, 1, 3) = t_f4_rrrr_0012
            f4_rrrr(1, 2, 3, 1) = t_f4_rrrr_0012
            f4_rrrr(1, 3, 1, 2) = t_f4_rrrr_0012
            f4_rrrr(1, 3, 2, 1) = t_f4_rrrr_0012
            f4_rrrr(2, 1, 1, 3) = t_f4_rrrr_0012
            f4_rrrr(2, 1, 3, 1) = t_f4_rrrr_0012
            f4_rrrr(2, 3, 1, 1) = t_f4_rrrr_0012
            f4_rrrr(3, 1, 1, 2) = t_f4_rrrr_0012
            f4_rrrr(3, 1, 2, 1) = t_f4_rrrr_0012
            f4_rrrr(3, 2, 1, 1) = t_f4_rrrr_0012
            t_f4_rrrr_0022 = &
               -inv_pd*pd4_rrrr(1, 1, 3, 3) + pd1_r(3)*x33 + pd1_r(3)*(pd1_r(3)*x30 - pd2_rr(1, &
               3)*x28 + x33) + pd2_rr(1, 3)*x39 + pd2_rr(3, 3)*x9 + x38*x6
            f4_rrrr(1, 1, 3, 3) = t_f4_rrrr_0022
            f4_rrrr(1, 3, 1, 3) = t_f4_rrrr_0022
            f4_rrrr(1, 3, 3, 1) = t_f4_rrrr_0022
            f4_rrrr(3, 1, 1, 3) = t_f4_rrrr_0022
            f4_rrrr(3, 1, 3, 1) = t_f4_rrrr_0022
            f4_rrrr(3, 3, 1, 1) = t_f4_rrrr_0022
            t_f4_rrrr_0111 = &
               -inv_pd*pd4_rrrr(1, 2, 2, 2) + pd1_r(1)*x40 + pd1_r(2)*x46 + pd2_rr(1, 2)*x19 + &
               pd2_rr(2, 2)*x35 + x18*x34
            f4_rrrr(1, 2, 2, 2) = t_f4_rrrr_0111
            f4_rrrr(2, 1, 2, 2) = t_f4_rrrr_0111
            f4_rrrr(2, 2, 1, 2) = t_f4_rrrr_0111
            f4_rrrr(2, 2, 2, 1) = t_f4_rrrr_0111
            t_f4_rrrr_0112 = &
               -inv_pd*pd4_rrrr(1, 2, 2, 3) + pd1_r(1)*x47 + pd1_r(3)*x46 + pd2_rr(1, 3)*x19 + &
               pd2_rr(2, 3)*x35 + x18*x37
            f4_rrrr(1, 2, 2, 3) = t_f4_rrrr_0112
            f4_rrrr(1, 2, 3, 2) = t_f4_rrrr_0112
            f4_rrrr(1, 3, 2, 2) = t_f4_rrrr_0112
            f4_rrrr(2, 1, 2, 3) = t_f4_rrrr_0112
            f4_rrrr(2, 1, 3, 2) = t_f4_rrrr_0112
            f4_rrrr(2, 2, 1, 3) = t_f4_rrrr_0112
            f4_rrrr(2, 2, 3, 1) = t_f4_rrrr_0112
            f4_rrrr(2, 3, 1, 2) = t_f4_rrrr_0112
            f4_rrrr(2, 3, 2, 1) = t_f4_rrrr_0112
            f4_rrrr(3, 1, 2, 2) = t_f4_rrrr_0112
            f4_rrrr(3, 2, 1, 2) = t_f4_rrrr_0112
            f4_rrrr(3, 2, 2, 1) = t_f4_rrrr_0112
            t_f4_rrrr_0122 = &
               -inv_pd*pd4_rrrr(1, 2, 3, 3) + pd1_r(1)*x48 + pd1_r(2)*x38 + pd1_r(3)*x37 + &
               pd1_r(3)*(-pd1_r(1)*x49 - pd1_r(2)*x50 + pd1_r(3)*x45 + pd3_rrr(1, 2, 3)*x0) + &
               pd2_rr(1, 3)*x20 + pd2_rr(2, 3)*x17 + pd2_rr(3, 3)*x14
            f4_rrrr(1, 2, 3, 3) = t_f4_rrrr_0122
            f4_rrrr(1, 3, 2, 3) = t_f4_rrrr_0122
            f4_rrrr(1, 3, 3, 2) = t_f4_rrrr_0122
            f4_rrrr(2, 1, 3, 3) = t_f4_rrrr_0122
            f4_rrrr(2, 3, 1, 3) = t_f4_rrrr_0122
            f4_rrrr(2, 3, 3, 1) = t_f4_rrrr_0122
            f4_rrrr(3, 1, 2, 3) = t_f4_rrrr_0122
            f4_rrrr(3, 1, 3, 2) = t_f4_rrrr_0122
            f4_rrrr(3, 2, 1, 3) = t_f4_rrrr_0122
            f4_rrrr(3, 2, 3, 1) = t_f4_rrrr_0122
            f4_rrrr(3, 3, 1, 2) = t_f4_rrrr_0122
            f4_rrrr(3, 3, 2, 1) = t_f4_rrrr_0122
            t_f4_rrrr_0222 = &
               -inv_pd*pd4_rrrr(1, 3, 3, 3) + pd1_r(1)*x51 + pd1_r(3)*(-pd1_r(1)*x52 - &
               pd1_r(3)*x50 + pd1_r(3)*(pd1_r(3)*x44 - x50) + pd3_rrr(1, 3, 3)*x0) + pd2_rr(1, &
               3)*x22 + pd2_rr(3, 3)*x39 + x21*x38
            f4_rrrr(1, 3, 3, 3) = t_f4_rrrr_0222
            f4_rrrr(3, 1, 3, 3) = t_f4_rrrr_0222
            f4_rrrr(3, 3, 1, 3) = t_f4_rrrr_0222
            f4_rrrr(3, 3, 3, 1) = t_f4_rrrr_0222
            f4_rrrr(2, 2, 2, 2) = &
               -inv_pd*pd4_rrrr(2, 2, 2, 2) + pd1_r(2)*x58 + pd2_rr(2, 2)*x55 + x40*x53
            t_f4_rrrr_1112 = &
               -inv_pd*pd4_rrrr(2, 2, 2, 3) + pd1_r(3)*x58 + pd2_rr(2, 3)*x55 + x47*x53
            f4_rrrr(2, 2, 2, 3) = t_f4_rrrr_1112
            f4_rrrr(2, 2, 3, 2) = t_f4_rrrr_1112
            f4_rrrr(2, 3, 2, 2) = t_f4_rrrr_1112
            f4_rrrr(3, 2, 2, 2) = t_f4_rrrr_1112
            t_f4_rrrr_1122 = &
               -inv_pd*pd4_rrrr(2, 2, 3, 3) + pd1_r(3)*x47 + pd1_r(3)*(pd1_r(3)*x57 - pd2_rr(2, &
               3)*x56 + x47) + pd2_rr(2, 3)*x59 + pd2_rr(3, 3)*x19 + x18*x48
            f4_rrrr(2, 2, 3, 3) = t_f4_rrrr_1122
            f4_rrrr(2, 3, 2, 3) = t_f4_rrrr_1122
            f4_rrrr(2, 3, 3, 2) = t_f4_rrrr_1122
            f4_rrrr(3, 2, 2, 3) = t_f4_rrrr_1122
            f4_rrrr(3, 2, 3, 2) = t_f4_rrrr_1122
            f4_rrrr(3, 3, 2, 2) = t_f4_rrrr_1122
            t_f4_rrrr_1222 = &
               -inv_pd*pd4_rrrr(2, 3, 3, 3) + pd1_r(2)*x51 + pd1_r(3)*(-pd1_r(2)*x52 - &
               pd1_r(3)*x49 + pd1_r(3)*(x4*x43 - x49) + pd3_rrr(2, 3, 3)*x0) + pd2_rr(2, 3)*x22 + &
               pd2_rr(3, 3)*x59 + x21*x48
            f4_rrrr(2, 3, 3, 3) = t_f4_rrrr_1222
            f4_rrrr(3, 2, 3, 3) = t_f4_rrrr_1222
            f4_rrrr(3, 3, 2, 3) = t_f4_rrrr_1222
            f4_rrrr(3, 3, 3, 2) = t_f4_rrrr_1222
            f4_rrrr(3, 3, 3, 3) = &
               -inv_pd*pd4_rrrr(3, 3, 3, 3) + 3.0_wp*pd1_r(3)*x51 + pd1_r(3)*(-pd1_r(3)*pd2_rr(3, &
               3)*x27 + pd1_r(3)*(x29*x60 - x52) + x51) + pd2_rr(3, 3)*(3.0_wp*pd2_rr(3, 3)*x0 - &
               x60*x7)
         end block
      end select

   end subroutine cfc_spatial_eval

   !> Lift the accumulated tensors to the level-set nuclear gradient.
   !>
   !> With ``S = -log PD`` and one retained nucleus A,
   !>
   !>    f{k+1}_..._rA(i1..ik, beta) = d/dR_A,beta  d^k S / dr_i1..dr_ik
   !>
   !> Two accumulated families feed it: `pd*` (`*_term_eval` /
   !> `cfc_pair_spatial_eval`, an aggregate) and `qn*` (`*_nuclear_eval`, atom
   !> A's own share).  No direction vector is involved, so a caller that wants
   !> only the nuclear gradient never touches the contracted families.
   !>
   !> Call once per atom A per evaluation point, i.e. O(n_active) in total.
   !>
   !> @param[in]    pd0        Accumulated order-0 spatial derivative of PD
   !> @param[in]    pd1_r      Accumulated order-1 spatial derivative of PD
   !> @param[in]    pd2_rr     Accumulated order-2 spatial derivative of PD
   !> @param[in]    pd3_rrr    Accumulated order-3 spatial derivative of PD
   !> @param[in]    qn0        Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qn1_r      Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qn2_rr     Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qn3_rrr    Atom-A d/dR_A of the order-3 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    max_deriv  Highest spatial-derivative order to lift (0..3); a larger value is
   !>                          treated as 3
   !> @param[out]   f1_rA      d/dR_A of the order-0 spatial derivative of the level set; trailing
   !>                          index is the nuclear component
   !> @param[out]   f2_r_rA    d/dR_A of the order-1 spatial derivative of the level set; trailing
   !>                          index is the nuclear component
   !> @param[out]   f3_rr_rA   d/dR_A of the order-2 spatial derivative of the level set; trailing
   !>                          index is the nuclear component
   !> @param[out]   f4_rrr_rA  d/dR_A of the order-3 spatial derivative of the level set; trailing
   !>                          index is the nuclear component
   pure subroutine cfc_nuclear_eval(pd0, pd1_r, pd2_rr, pd3_rrr, qn0, qn1_r, qn2_rr, qn3_rrr, &
                                    max_deriv, f1_rA, f2_r_rA, f3_rr_rA, f4_rrr_rA)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated order-3 spatial derivative of PD
      real(wp), intent(in) :: pd3_rrr(3, 3, 3)
      !> Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn0(3)
      !> Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn1_r(3, 3)
      !> Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn2_rr(3, 3, 3)
      !> Atom-A d/dR_A of the order-3 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn3_rrr(3, 3, 3, 3)
      !> Highest spatial-derivative order to lift (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dR_A of the order-0 spatial derivative of the level set; trailing index is the nuclear
      !> component
      real(wp), intent(out) :: f1_rA(3)
      !> d/dR_A of the order-1 spatial derivative of the level set; trailing index is the nuclear
      !> component
      real(wp), intent(out) :: f2_r_rA(3, 3)
      !> d/dR_A of the order-2 spatial derivative of the level set; trailing index is the nuclear
      !> component
      real(wp), intent(out) :: f3_rr_rA(3, 3, 3)
      !> d/dR_A of the order-3 spatial derivative of the level set; trailing index is the nuclear
      !> component
      real(wp), intent(out) :: f4_rrr_rA(3, 3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      f1_rA = 0.0_wp
      f2_r_rA = 0.0_wp
      f3_rr_rA = 0.0_wp
      f4_rrr_rA = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            f1_rA(1) = -inv_pd*qn0(1)
            f1_rA(2) = -inv_pd*qn0(2)
            f1_rA(3) = -inv_pd*qn0(3)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = pd1_r(2)*x0
            x3 = pd1_r(3)*x0
            f1_rA(1) = -inv_pd*qn0(1)
            f1_rA(2) = -inv_pd*qn0(2)
            f1_rA(3) = -inv_pd*qn0(3)
            f2_r_rA(1, 1) = -inv_pd*qn1_r(1, 1) + qn0(1)*x1
            f2_r_rA(1, 2) = -inv_pd*qn1_r(1, 2) + qn0(2)*x1
            f2_r_rA(1, 3) = -inv_pd*qn1_r(1, 3) + qn0(3)*x1
            f2_r_rA(2, 1) = -inv_pd*qn1_r(2, 1) + qn0(1)*x2
            f2_r_rA(2, 2) = -inv_pd*qn1_r(2, 2) + qn0(2)*x2
            f2_r_rA(2, 3) = -inv_pd*qn1_r(2, 3) + qn0(3)*x2
            f2_r_rA(3, 1) = -inv_pd*qn1_r(3, 1) + qn0(1)*x3
            f2_r_rA(3, 2) = -inv_pd*qn1_r(3, 2) + qn0(2)*x3
            f2_r_rA(3, 3) = -inv_pd*qn1_r(3, 3) + qn0(3)*x3
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14
            real(wp) :: t_f3_rr_rA_010, t_f3_rr_rA_011, t_f3_rr_rA_012, t_f3_rr_rA_020
            real(wp) :: t_f3_rr_rA_021, t_f3_rr_rA_022, t_f3_rr_rA_120, t_f3_rr_rA_121
            real(wp) :: t_f3_rr_rA_122

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = pd1_r(2)*x0
            x3 = pd1_r(3)*x0
            x4 = 2.0_wp*x1
            x5 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
            x6 = -(pd1_r(1)*pd1_r(1))*x5 + pd2_rr(1, 1)*x0
            x7 = pd1_r(1)*x5
            x8 = -pd1_r(2)*x7 + pd2_rr(1, 2)*x0
            x9 = -pd1_r(3)*x7 + pd2_rr(1, 3)*x0
            x10 = 2.0_wp*x2
            x11 = -(pd1_r(2)*pd1_r(2))*x5 + pd2_rr(2, 2)*x0
            x12 = -pd1_r(2)*pd1_r(3)*x5 + pd2_rr(2, 3)*x0
            x13 = 2.0_wp*x3
            x14 = -(pd1_r(3)*pd1_r(3))*x5 + pd2_rr(3, 3)*x0
            f1_rA(1) = -inv_pd*qn0(1)
            f1_rA(2) = -inv_pd*qn0(2)
            f1_rA(3) = -inv_pd*qn0(3)
            f2_r_rA(1, 1) = -inv_pd*qn1_r(1, 1) + qn0(1)*x1
            f2_r_rA(1, 2) = -inv_pd*qn1_r(1, 2) + qn0(2)*x1
            f2_r_rA(1, 3) = -inv_pd*qn1_r(1, 3) + qn0(3)*x1
            f2_r_rA(2, 1) = -inv_pd*qn1_r(2, 1) + qn0(1)*x2
            f2_r_rA(2, 2) = -inv_pd*qn1_r(2, 2) + qn0(2)*x2
            f2_r_rA(2, 3) = -inv_pd*qn1_r(2, 3) + qn0(3)*x2
            f2_r_rA(3, 1) = -inv_pd*qn1_r(3, 1) + qn0(1)*x3
            f2_r_rA(3, 2) = -inv_pd*qn1_r(3, 2) + qn0(2)*x3
            f2_r_rA(3, 3) = -inv_pd*qn1_r(3, 3) + qn0(3)*x3
            f3_rr_rA(1, 1, 1) = -inv_pd*qn2_rr(1, 1, 1) + qn0(1)*x6 + qn1_r(1, 1)*x4
            f3_rr_rA(1, 1, 2) = -inv_pd*qn2_rr(1, 1, 2) + qn0(2)*x6 + qn1_r(1, 2)*x4
            f3_rr_rA(1, 1, 3) = -inv_pd*qn2_rr(1, 1, 3) + qn0(3)*x6 + qn1_r(1, 3)*x4
            t_f3_rr_rA_010 = -inv_pd*qn2_rr(1, 2, 1) + qn0(1)*x8 + qn1_r(1, 1)*x2 + qn1_r(2, 1)*x1
            f3_rr_rA(1, 2, 1) = t_f3_rr_rA_010
            f3_rr_rA(2, 1, 1) = t_f3_rr_rA_010
            t_f3_rr_rA_011 = -inv_pd*qn2_rr(1, 2, 2) + qn0(2)*x8 + qn1_r(1, 2)*x2 + qn1_r(2, 2)*x1
            f3_rr_rA(1, 2, 2) = t_f3_rr_rA_011
            f3_rr_rA(2, 1, 2) = t_f3_rr_rA_011
            t_f3_rr_rA_012 = -inv_pd*qn2_rr(1, 2, 3) + qn0(3)*x8 + qn1_r(1, 3)*x2 + qn1_r(2, 3)*x1
            f3_rr_rA(1, 2, 3) = t_f3_rr_rA_012
            f3_rr_rA(2, 1, 3) = t_f3_rr_rA_012
            t_f3_rr_rA_020 = -inv_pd*qn2_rr(1, 3, 1) + qn0(1)*x9 + qn1_r(1, 1)*x3 + qn1_r(3, 1)*x1
            f3_rr_rA(1, 3, 1) = t_f3_rr_rA_020
            f3_rr_rA(3, 1, 1) = t_f3_rr_rA_020
            t_f3_rr_rA_021 = -inv_pd*qn2_rr(1, 3, 2) + qn0(2)*x9 + qn1_r(1, 2)*x3 + qn1_r(3, 2)*x1
            f3_rr_rA(1, 3, 2) = t_f3_rr_rA_021
            f3_rr_rA(3, 1, 2) = t_f3_rr_rA_021
            t_f3_rr_rA_022 = -inv_pd*qn2_rr(1, 3, 3) + qn0(3)*x9 + qn1_r(1, 3)*x3 + qn1_r(3, 3)*x1
            f3_rr_rA(1, 3, 3) = t_f3_rr_rA_022
            f3_rr_rA(3, 1, 3) = t_f3_rr_rA_022
            f3_rr_rA(2, 2, 1) = -inv_pd*qn2_rr(2, 2, 1) + qn0(1)*x11 + qn1_r(2, 1)*x10
            f3_rr_rA(2, 2, 2) = -inv_pd*qn2_rr(2, 2, 2) + qn0(2)*x11 + qn1_r(2, 2)*x10
            f3_rr_rA(2, 2, 3) = -inv_pd*qn2_rr(2, 2, 3) + qn0(3)*x11 + qn1_r(2, 3)*x10
            t_f3_rr_rA_120 = -inv_pd*qn2_rr(2, 3, 1) + qn0(1)*x12 + qn1_r(2, 1)*x3 + qn1_r(3, 1)*x2
            f3_rr_rA(2, 3, 1) = t_f3_rr_rA_120
            f3_rr_rA(3, 2, 1) = t_f3_rr_rA_120
            t_f3_rr_rA_121 = -inv_pd*qn2_rr(2, 3, 2) + qn0(2)*x12 + qn1_r(2, 2)*x3 + qn1_r(3, 2)*x2
            f3_rr_rA(2, 3, 2) = t_f3_rr_rA_121
            f3_rr_rA(3, 2, 2) = t_f3_rr_rA_121
            t_f3_rr_rA_122 = -inv_pd*qn2_rr(2, 3, 3) + qn0(3)*x12 + qn1_r(2, 3)*x3 + qn1_r(3, 3)*x2
